window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["pc62258248f"]={"id":"pc62258248f","name":"2025年广西区考公务员录用考试《行测》题（网友回忆版）","year":2025,"region":"广西","count":71,"types":{"马克思主义":1,"新思想":5,"时事政治":4,"逻辑填空":13,"片段阅读":9,"语句表达":4,"图形推理":10,"定义判断":10,"类比推理":5,"逻辑判断":10},"modules":["政治理论","言语理解与表达","判断推理"],"questions":[{"qid":"13504351","no":1,"type":"马克思主义","module":"政治理论","stem":"<p>习近平总书记指出，“两个结合”是我们取得成功的最大法宝。关于“两个结合”，下列表述正确的有几项？<br>①“两个结合”筑牢了道路根基，中国特色的关键就在于“两个结合”<br>②“两个结合”本身就是创新，同时又开启了广阔的理论和实践创新空间<br>③“两个结合”产生了深刻的“化学反应”，造就了一个有机统一的新的文化生命体<br>④“两个结合”是坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>2023年6月2日，中共中央总书记、国家主席、中央军委主席习近平在北京出席文化传承发展座谈会并发表重要讲话。<br>①正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，第三，“结合”筑牢了道路根基。中国特色的关键就在于“两个结合”。“第二个结合”让中国特色社会主义道路有了更加宏阔深远的历史纵深，拓展了中国特色社会主义道路的文化根基。<br>②正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，第四，“结合”打开了创新空间。“结合”本身就是创新，同时又开启了广阔的理论和实践创新空间。“第二个结合”让我们掌握了思想和文化主动，并有力地作用于道路、理论和制度。<br>③正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，第二，“结合”的结果是互相成就。“结合”不是“拼盘”，不是简单的“物理反应”，而是深刻的“化学反应”，造就了一个有机统一的新的文化生命体。<br>④正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，在五千多年中华文明深厚基础上开辟和发展中国特色社会主义，把马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合是必由之路。这是我们在探索中国特色社会主义道路中得出的规律性认识。<br>故正确的有①②③④，共4项。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"pc62258248f"},{"qid":"13504309","no":2,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，中国将坚持推进高水平对外开放，以高质量发展全面推进中国式现代化，为各国开放合作提供新机遇。关于推进高水平对外开放，下列举措恰当的有几项？<br>①维护多元稳定的国际经济格局和经贸关系<br>②加强知识产权保护，营造良好的营商环境<br>③稳步扩大规则、规制、管理、标准等制度型开放<br>④减少对外资企业的准入限制，全面放开所有行业领域<br>⑤加快建设贸易强国，推动共建“一带一路”高质量发展</p>","options":[{"k":"A","t":"2"},{"k":"B","t":"3"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>①③⑤正确，④错误，党的二十大报告“四、加快构建新发展格局，着力推动高质量发展”部分指出：“（五）推进高水平对外开放。依托我国超大规模市场优势，以国内大循环吸引全球资源要素，增强国内国际两个市场两种资源联动效应，提升贸易投资合作质量和水平。稳步扩大规则、规制、管理、标准等制度型开放。推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易，加快建设贸易强国。合理缩减外资准入负面清单，依法保护外商投资权益，营造市场化、法治化、国际化一流营商环境。推动共建‘一带一路’高质量发展。优化区域开放布局，巩固东部沿海地区开放先导地位，提高中西部和东北地区开放水平。加快建设西部陆海新通道。加快建设海南自由贸易港，实施自由贸易试验区提升战略，扩大面向全球的高标准自由贸易区网络。有序推进人民币国际化。深度参与全球产业分工和合作，维护多元稳定的国际经济格局和经贸关系。”减少外资准入限制是推进对外开放的重要举措，但“全面放开所有行业领域”表述过于绝对，某些关键领域仍需保留一定的限制，以确保国家利益和安全。<br>②正确，习近平总书记在重要文章《全面加强知识产权保护工作 激发创新活力推动构建新发展格局》中指出：“创新是引领发展的第一动力，保护知识产权就是保护创新······知识产权保护工作关系国家对外开放大局，只有严格保护知识产权，才能优化营商环境、建设更高水平开放型经济新体制。知识产权保护工作关系国家安全，只有严格保护知识产权，才能有效保护我国自主研发的关键核心技术、防范化解重大风险。”<br>故①②③⑤表述正确，有4项。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"pc62258248f"},{"qid":"13504329","no":3,"type":"时事政治","module":"政治理论","stem":"<p>党的二十大报告指出，构建全国统一大市场，深化要素市场化改革，建设高标准市场体系。关于构建全国统一大市场，下列与之相关说法错误的是：</p>","options":[{"k":"A","t":"推动市场基础制度规则统一"},{"k":"B","t":"加强公平竞争审查柔性约束"},{"k":"C","t":"规范地方招商引资法规制度"},{"k":"D","t":"深化地方标准管理制度改革"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>B项错误，A、C、D三项正确，《中共中央关于进一步全面深化改革 推进中国式现代化的决定》在“二、构建高水平社会主义市场经济体制”部分“（6）构建全国统一大市场”中指出：“推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通。加强公平竞争审查刚性约束，强化反垄断和反不正当竞争，清理和废除妨碍全国统一市场和公平竞争的各种规定和做法。规范地方招商引资法规制度，严禁违法违规给予政策优惠行为。建立健全统一规范、信息共享的招标投标和政府、事业单位、国有企业采购等公共资源交易平台体系，实现项目全流程公开管理。提升市场综合监管能力和水平。健全国家标准体系，深化地方标准管理制度改革。”故B项中“柔性约束”说法错误。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"pc62258248f"},{"qid":"13504328","no":4,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届三中全会指出，法治是中国式现代化的重要保障。下列不属于完善中国特色社会主义法治体系举措的是：</p>","options":[{"k":"A","t":"健全基层民主制度"},{"k":"B","t":"深入推进依法行政"},{"k":"C","t":"深化立法领域改革"},{"k":"D","t":"加强涉外法治建设"}],"answer":"A","multi":false,"explanation":"<p>本题考查理论与政策。<br>A项错误，中国共产党第二十届中央委员会第三次全体会议提出，发展全过程人民民主是中国式现代化的本质要求。必须坚定不移走中国特色社会主义政治发展道路，坚持和完善我国根本政治制度、基本政治制度、重要政治制度，丰富各层级民主形式，把人民当家作主具体、现实体现到国家政治生活和社会生活各方面。要加强人民当家作主制度建设，健全协商民主机制，健全基层民主制度，完善大统战工作格局。<br>B、C、D三项正确，中国共产党第二十届中央委员会第三次全体会议提出，法治是中国式现代化的重要保障。必须全面贯彻实施宪法，维护宪法权威，协同推进立法、执法、司法、守法各环节改革，健全法律面前人人平等保障机制，弘扬社会主义法治精神，维护社会公平正义，全面推进国家各方面工作法治化。要深化立法领域改革，深入推进依法行政，健全公正执法司法体制机制，完善推进法治社会建设机制，加强涉外法治建设。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"pc62258248f"},{"qid":"13504370","no":5,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，现代化产业体系是现代化国家的物质技术基础，必须把发展经济的着力点放在实体经济上，为实现第二个百年奋斗目标提供坚强物质支撑。下列与之相关说法正确的有几项？<br>①推进实施绿色发展战略，充分发挥绿色化赋能实体经济发展效应<br>②促进数字技术和实体经济深度融合，催生新产业新业态新模式替代传统产业<br>③重视现代服务业的发展，推动现代服务业与先进制造业、现代农业深度融合<br>④推动重点产业在国内外有序转移、促进国内外产业深度融合与实体经济发展相结合</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，《新型工业化是发展新质生产力的主阵地》中指出，习近平总书记强调：“要充分认识形成绿色发展方式和生活方式的重要性、紧迫性、艰巨性。”······因此，要推动绿色发展与实体经济发展相融合，充分发挥绿色化赋能实体经济发展效应。<br>②错误，《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》中指出，促进数字技术与实体经济深度融合，赋能传统产业转型升级，催生新产业新业态新模式，壮大经济发展新引擎。<br>③正确，《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》中指出，重视现代服务业的发展，推动现代服务业与先进制造业、现代农业深度融合，深化业务关联、链条延伸、技术渗透，支持智能制造系统解决方案、流程再造等新型专业化服务机构发展。培育具有国际竞争力的服务企业。<br>④正确，习近平总书记在二十届中央政治局第二次集体学习时强调，优化生产力布局，推动重点产业在国内外有序转移，支持企业深度参与全球产业分工和合作，促进内外产业深度融合，打造自主可控、安全可靠、竞争力强的现代化产业体系。这要求我们发挥好超大规模市场优势和超大纵深空间优势，加快建设以实体经济为支撑的现代化产业体系，引导产业合理有序梯度转移。<br>故①③④表述正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":4,"pid":"pc62258248f"},{"qid":"13504327","no":6,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，纪检监察机关是推进党的自我革命的重要力量，党和人民对这支队伍充分信任、充满期待，下列与之相关说法正确的有几项？<br>①巩固拓展主题教育和教育整顿成果，坚持把思想教育放在首位<br>②强化严格管理监督，打造忠诚干净担当、敢于善于斗争的纪检监察铁军<br>③深化纪检监察体制改革，坚持授权和控权相结合，把权力关进制度的笼子<br>④着力加强纪检监察工作规范化法治化正规化建设，不断提高正风肃纪反腐能力</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>①错误，②③④正确，2025年1月6日，习近平总书记在中国共产党第二十届中央纪律检查委员会第四次全体会议上发表重要讲话。习近平总书记在讲话中强调：“纪检监察机关是推进党的自我革命的重要力量，党和人民对这支队伍充分信任、充满期待。要深化纪检监察体制改革，坚持授权和控权相结合，把权力关进制度的笼子。要着力加强纪检监察工作规范化法治化正规化建设，不断提高正风肃纪反腐能力。要巩固拓展主题教育和教育整顿成果，坚持打铁必须自身硬，强化严格管理监督，打造忠诚干净担当、敢于善于斗争的纪检监察铁军。”<br>综上，②③④说法正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":5,"pid":"pc62258248f"},{"qid":"13504287","no":7,"type":"时事政治","module":"政治理论","stem":"<p>2024年12月，中央农村工作会议在北京召开，会议对如何做好“三农”工作进行了具体部署，下列与之相关说法错误的是：</p>","options":[{"k":"A","t":"加强新时代农村精神文明建设，积极开展移风易俗"},{"k":"B","t":"提高农村基本公共服务水平，持续改善农村人居环境"},{"k":"C","t":"推进农业科技力量协同攻关，因地制宜发展农业新质生产力"},{"k":"D","t":"完善农产品贸易与生产协调机制，推动粮食等农产品价格稳步提升"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>D项错误，A、B、C三项正确，2024年中央农村工作会议强调，要聚焦学习运用“千万工程”经验、推进乡村全面振兴······推进农业科技力量协同攻关，加快科技成果大面积推广应用，因地制宜发展农业新质生产力······完善农产品贸易与生产协调机制，推动粮食等重要农产品价格保持在合理水平······推动基础设施向农村延伸，提高农村基本公共服务水平，持续改善农村人居环境，加强农村生态环境治理······实施文明乡风建设工程，加强新时代农村精神文明建设，积极开展移风易俗。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":6,"pid":"pc62258248f"},{"qid":"13504294","no":8,"type":"新思想","module":"政治理论","stem":"<p>实现中华民族伟大复兴的中国梦不可能一马平川，我们要居安思危、未雨绸缪，坚决战胜一切不确定难预料的风险挑战。任何困难都无法阻挡中国人民前进的步伐，我们要居安思危、未雨绸缪，是因为：</p>","options":[{"k":"A","t":"人类社会历史发展是前进性与曲折性的辩证统一"},{"k":"B","t":"社会规律是在各种因素的相互作用过程中自发实现的"},{"k":"C","t":"通过充分发挥主观能动性，就能消除事物发展中的偶然方面"},{"k":"D","t":"本质与现象是相互依存的，所有现象都在一定程度上表现本质"}],"answer":"A","multi":false,"explanation":"<p>本题考查马克思主义。<br>“居安思危”是指处于安全的环境下，也要预判可能出现的危险。“未雨绸缪”比喻事先做好准备工作，防止意外的发生。<br>A项正确，题干中强调“实现中华民族伟大复兴的中国梦不可能一马平川”，其中，实现中华民族伟大复兴的中国梦是历史发展的必然趋势，具有前进性，但中国梦的实现不是一帆风顺，有一定的曲折性。要居安思危、未雨绸缪，就是要正视前进性的曲折，做好准备工作，符合题意。<br>B项错误，社会规律是通过人们的自觉活动实现的，需要人的有意识、有目的的活动参与，不是在各种因素的相互作用过程中自发实现的。<br>C项错误，事物的发展是由必然性和偶然性共同决定的。必然性是指事物发展过程中不可避免、确定的因素，偶然性则是指事物发展过程中不确定、可能改变的因素。但是，偶然性往往是难以完全预见和控制的。因此，通过充分发挥主观能动性，并不能消除事物发展中的偶然方面。<br>D项错误，本质是事物的根本性质，是构成事物的诸要素之间的内在联系，是相对稳定的。现象是事物的外部联系和表面特征，是多变易逝的。本质总是通过一定的现象表现自己的存在。表述正确，但是和材料无关。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":7,"pid":"pc62258248f"},{"qid":"13504288","no":9,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届三中全会提出，要推动建设生育友好型社会。关于推动建设生育友好型社会，下列举措不恰当的是：</p>","options":[{"k":"A","t":"指导各地推动养育、教育产业市场化发展"},{"k":"B","t":"鼓励各地出台多孩子女同校就读具体实施办法"},{"k":"C","t":"指导各地将辅助生殖技术项目纳入医保报销范围"},{"k":"D","t":"指导有条件的地方将参加职工基本医疗保险的灵活就业人员纳入生育保险"}],"answer":"A","multi":false,"explanation":"<p>本题考查理论与政策。<br>2024年10月19日，国务院办公厅印发《关于加快完善生育支持政策体系推动建设生育友好型社会的若干措施》（以下简称《措施》）。<br>A项错误，《措施》在“一、总体要求”部分指出：“以习近平新时代中国特色社会主义思想为指导······完善生育支持政策体系和激励机制，健全覆盖全人群、全生命周期的人口服务体系，有效降低生育、养育、教育成本，营造全社会尊重生育、支持生育的良好氛围，为推动实现适度生育水平、促进人口高质量发展提供有力支撑。”由此可见，推动养育、教育产业市场化发展说法错误。<br>B项正确，《措施》在“四、强化教育、住房、就业等支持措施”部分“（九）扩大优质教育资源供给”中指出：“优化区域教育资源配置······鼓励各地出台多孩子女同校就读具体实施办法，帮助解决家长接送不便问题。”<br>C项正确，《措施》在“二、强化生育服务支持”部分“（四）加强生殖健康服务”中指出：“深入实施母婴安全行动提升计划和出生缺陷防治能力提升计划······加强生育医疗费用保障，指导各地将适宜的分娩镇痛以及辅助生殖技术项目纳入医保报销范围。”<br>D项正确，《措施》在“二、强化生育服务支持”部分“（一）增强生育保险保障功能”中指出：“强化生育保险对参保女职工生育医疗费用、生育津贴待遇等保障作用。指导有条件的地方将参加职工基本医疗保险的灵活就业人员、农民工、新就业形态人员纳入生育保险。”<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":8,"pid":"pc62258248f"},{"qid":"13504334","no":10,"type":"新思想","module":"政治理论","stem":"<p>深化养老服务改革发展是实施积极应对人口老龄化国家战略的迫切要求，是保障和改善民生的重要任务，事关亿万百姓福祉，事关社会和谐稳定，为加快建设适合我国国情的养老服务体系，更好保障老有所养，下列举措恰当的是：<br>①推动国有资本参与发展养老服务，完善分类考核评价<br>②加快补齐农村养老服务短板，扩大农村养老服务供给<br>③发挥社区养老的决定作用，为居家养老提供有力支持<br>④以失能老年人的照护为重点，强化我国基本养老服务</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>2024年12月30日，中共中央 国务院发布了《关于深化养老服务改革发展的意见》（以下简称《意见》）。<br>①正确，《意见》在“四、构建养老服务事业产业发展三方协同机制”部分指出：“发挥养老服务产业发展市场配置资源作用······推动国有资本参与发展养老服务，完善分类考核评价。”<br>②正确，《意见》在“三、贯通协调居家社区机构三类养老服务形态”部分指出：“加快补齐农村养老服务短板。因地制宜扩大农村养老服务供给。”<br>③错误，《意见》在“三、贯通协调居家社区机构三类养老服务形态”部分指出：“强化社区养老依托作用。扩大社区养老服务有效供给，依托社区为居家养老提供有力支持。”故“社区养老的决定作用”说法有误。<br>④正确，《意见》在“一、总体要求”部分指出：“加快健全养老服务网络，优化居家为基础、社区为依托、机构为专业支撑、医养相结合的养老服务供给格局，强化以失能老年人照护为重点的基本养老服务，健全分级分类、普惠可及、覆盖城乡、持续发展的养老服务体系······”<br>故正确的有①②④。<br>故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":9,"pid":"pc62258248f"},{"qid":"13504261","no":1,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>对分类学者来说，与其说是找到新物种，不如说是碰到新物种。新物种的发现往往并非<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，而是意外之喜。在阅读文献、野外调查、查阅图片或者研究标本时，分类学者偶尔会发现某份标本或者个体跟之前的记录不一样，进而通过形态学比较或者分子测序手段确认该物种是否属于新的物种。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"守株待兔"},{"k":"B","t":"刻舟求剑"},{"k":"C","t":"照本宣科"},{"k":"D","t":"按图索骥"}],"answer":"D","multi":false,"explanation":"<p>根据“并非······而是”可知，横线处所填成语与“意外之喜”构成反义并列，且根据前文“不如说是碰到新物种”以及后文“偶尔会发现某份标本或者个体跟之前的记录不一样”可知，新物种并不是通过以往的记录或文献发现的，而是偶然间发现的，故横线处所填成语需体现通过以往的资料或线索发现之意。D项“按图索骥”比喻依照线索去寻找事物，符合文意，当选。<br>A项“守株待兔”比喻死守狭隘的经验不知变通，也讽刺妄想不劳而获的侥幸心理，B项“刻舟求剑”比喻办事刻板拘泥，不知根据实际情况处理问题，均与文意不符，排除；<br>C项“照本宣科”形容讲课、发言等死板地按照课文、讲稿，没有发挥，不生动，与“新物种的发现”搭配不当，排除。<br>故正确答案为D。<br>【文段出处】《哪里更容易碰到新物种？》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":10,"pid":"pc62258248f"},{"qid":"13504382","no":2,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>很多短视频不会提供更多的、有助于消除不确定性的信息，标题几乎就是其内容的全部。在标题的暗示下，网友被误导从而更容易相信某个被放大的碎片就是完整真相，所以短视频时代的“标题党”可能带来的破坏力就更加<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"昭然若揭"},{"k":"B","t":"难以名状"},{"k":"C","t":"显而易见"},{"k":"D","t":"不容小觑"}],"answer":"D","multi":false,"explanation":"<p>根据“网友被误导从而更容易相信某个被放大的碎片就是完整真相”可知，横线处所填成语需表达出短视频时代“标题党”可能带来的破坏力会很大、不能忽视之意。D项“不容小觑”指不能小看，不能轻视，符合文意，当选。<br>A项“昭然若揭”指含义非常明显或真相完全暴露，侧重坏事被揭露，与文意不符，排除；B项“难以名状”指难以形容、描述，侧重无法形容，文意明确指出破坏力不能忽视之意，与文意不符，排除；C项“显而易见”指事情或道理很明显，极容易看清，侧重事情本身较明显，文段侧重“标题党”所带来的消极影响很大，与文意不符，排除。<br>故正确答案为D。<br>【文段出处】《浙江宣传|别让“标题党”在短视频上蔓延》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":11,"pid":"pc62258248f"},{"qid":"13504279","no":3,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>食品数字标签，相当于电子“身份证”，通过二维码等形式展示食品的标签信息，消费者可以扫描食品标签上的二维码，通过页面放大、语音识读、视频讲解等多种功能，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地获取食品的相关信息。比如，食品的名称、配料表、生产日期和保质期、营养成分表等信息，消费者<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"持续 一览无遗"},{"k":"B","t":"实时 一清二楚"},{"k":"C","t":"详尽 一举两得"},{"k":"D","t":"便捷 一目了然"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“消费者可以扫描食品标签上的二维码”“比如，食品的名称、配料表、生产日期和保质期、营养成分表等信息”可知，文段强调通过食品数字标签，消费者获取食品相关信息非常便利，且获取的信息全面，故横线处所填词语要体现便利、全面之意，C项“详尽”指详细全面，没有遗漏，D项“便捷”指方便快捷，均符合文意，保留。A项“持续”指连续不断，与“扫码”这一动作不匹配，排除；B项“实时”指在某事发生、发展的实际时间同步做某事，与文段“比如”之后列举的内容不符，排除。<br>第二空，根据“消费者可以扫描食品标签上的二维码······获取食品的相关信息”“比如，食品的名称、配料表、生产日期和保质期、营养成分表等信息”可知，文段强调消费者对于食品相关信息清楚了解，故横线处所填成语要体现清楚之意，D项“一目了然”形容事物、事情原委很清晰，一看就知道是怎么回事，符合文意，当选。C项“一举两得”指做一件事，同时收获两方面的好处，文段未提及两方面好处，排除。<br>故正确答案为D。<br>【文段出处】红网《食品数字标签保护“舌尖上的安全”》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":12,"pid":"pc62258248f"},{"qid":"12882019","no":4,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>通过迁地保护、建立常态化监测体系、保护和修复野生动植物赖以生存的生态家园等一系列举措，云南许多珍稀动植物的命运正在被<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。滇金丝猴数量增长到3300余只，西黑冠长臂猿、绿孔雀等20多种野生动物种群数量也大幅上升；漾濞槭、华盖木等30种极小种群野生植物<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>灭绝威胁。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"改编 挣脱"},{"k":"B","t":"改写 脱离"},{"k":"C","t":"改变 面临"},{"k":"D","t":"修改 受到"}],"answer":"B","multi":false,"explanation":"<p>第一空，搭配“命运”，根据前文可知，横线处表达一系列举措对云南许多动植物命运产生积极影响，B项“改写”指变换另一种写法，C项“改变”指使发生变化，均与“命运”搭配恰当，且符合文意，保留。A项“改编”指根据原著重新编写，D项“修改”指改正文章、计划等里面的错误、缺点，均与“命运”搭配不当，排除。<br>第二空，根据前文可知，一系列举措对云南许多珍稀动植物起到积极作用，横线处应表达不再面临灭绝威胁之意。B项“脱离”指离开（某种环境或情况），符合文意，当选。C项“面临”指面前遇到（问题、形势等），与文意相悖，排除。<br>故正确答案为B。<br>【文段出处】光明日报《解码生物多样性保护的云南经验》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":13,"pid":"pc62258248f"},{"qid":"13504263","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>山西的珍贵古建筑为现代艺术创作提供了无尽的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。《黑神话：悟空》游戏开发者们深入挖掘山西古建筑中的艺术瑰宝，巧妙地将27处极具代表性的古建筑融入游戏设计中。游戏场景中，“亢金龙”“虚日鼠”等藏于晋城玉皇庙里的二十八星宿塑像被复刻得<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，使越来越多的人体验到中国的古建之美和文化之韵。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"巧思 跃然纸上"},{"k":"B","t":"灵感 栩栩如生"},{"k":"C","t":"参考 惟妙惟肖"},{"k":"D","t":"想象 绘声绘色"}],"answer":"B","multi":false,"explanation":"<p>第一空，搭配“无尽”，根据“《黑神话：悟空》游戏开发者们深入挖掘山西古建筑中的艺术瑰宝，巧妙地将27处极具代表性的古建筑融入游戏设计中”可知，现代艺术创作者从古建筑中获取到了设计游戏的思路。A项“巧思”指灵巧的心思或巧妙的构思，B项“灵感”指在文学、艺术、科学、技术等活动中，突然产生的富有创造性的思路，均符合文意，保留。C项“参考”指在处理事物时借鉴、利用有关材料，与“无尽”搭配不当，排除；D项“想象”指人类在头脑中对已有的表象进行加工改造，创造出新形象的心理过程，而文段强调的是从真实存在的山西古建筑中获取创作元素，与文意相悖，排除。<br>第二空，搭配“二十八星宿塑像”，且根据“使越来越多的人体验到中国的古建之美和文化之韵”可知，横线处成语与后文构成因果关系，应体现复刻效果极具真实感之意。B项“栩栩如生”指艺术形象非常逼真，如同活的一样，符合文意且搭配恰当，当选。A项“跃然纸上”形容描写或刻画得十分生动逼真，多用于文学或绘画领域，“纸上”这一表述显然与“二十八星宿塑像”搭配不当，排除。<br>故正确答案为B。<br>【文段出处】光明日报《山西：数智助力 古建出圈》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":14,"pid":"pc62258248f"},{"qid":"13504384","no":6,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>品牌建设是一项长期性、战略性任务，也是一项系统工程。要抓住机遇，直面挑战，用好物质基础雄厚、人力资源丰富、市场空间广阔等<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，坚决解决部分产品质量和性能欠佳的“硬伤”，做细做精做强，不断提升品牌的内在价值，让有竞争力的品牌<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"要素 崭露头角"},{"k":"B","t":"资本 声名鹊起"},{"k":"C","t":"优势 脱颖而出"},{"k":"D","t":"条件 百尺竿头"}],"answer":"C","multi":false,"explanation":"<p>第一空，与“物质基础雄厚、人力资源丰富、市场空间广阔等”搭配，且根据文意可知，横线处所填词语应表达品牌建设需要利用好这些资源之意。A项“要素”指构成事物的必要因素，C项“优势”指能超过对方的有利形势，D项“条件”指影响事物发生、存在或发展的因素，均符合文意，保留。B项“资本”比喻牟取利益的凭借，与“市场空间广阔”搭配不当，排除。<br>第二空，根据横线前“品牌建设······要抓住机遇，直面挑战”以及“做细做精做强，不断提升品牌的内在价值”可知，横线处所填成语应体现让有竞争力的品牌得到充分发展的意思。C项“脱颖而出”比喻人的才能全部显示出来，多用于竞争的语境当中，与“有竞争力的品牌”搭配恰当，当选。A项“崭露头角”比喻突出地显露出才能和本领，多用于形容事物发展初期或起步阶段，与文意不符，排除；D项“百尺竿头”比喻学问、成绩等达到了很高的程度以后仍继续努力，与文意不符，排除。<br>故正确答案为C。<br>【文段出处】《以品牌建设助推高质量发展》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":15,"pid":"pc62258248f"},{"qid":"13504278","no":7,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>近年来，“打卡无人区”成为一些人的时髦选择，诸如青海可可西里、新疆罗布泊等人迹罕至的自然保护区，成了不少人<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的人间秘境。但是，“无人区”及自然生态保护区，远没有外界想象得那么浪漫和神秘。每个游客及旅行团都要深刻认识到这类地区的极端危险性，切莫仅凭一腔热血与<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，就盲目进发。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"念兹在兹 臆想"},{"k":"B","t":"念念不忘 激情"},{"k":"C","t":"心驰神往 好奇"},{"k":"D","t":"心醉神迷 勇气"}],"answer":"C","multi":false,"explanation":"<p>第一空，横线处搭配“人间秘境”，且根据“时髦选择”可知，文段表达人迹罕至的自然保护区成为很多人向往的地方，C项“心驰神往”形容思想集中在追求和向往的事情或地方上，一心向往，搭配恰当，符合文意，保留。A项“念兹在兹”指念念不忘某一件事情，与“人间秘境”搭配不当，排除；B项“念念不忘”指牢记于心，时刻不忘，搭配地点时多搭配去过的地方，文段中并没有去过，与文意不符，排除；D项“心醉神迷”形容佩服爱慕到极点，程度过重，排除。<br>第二空，代入验证，根据“每个游客及旅行团都要深刻认识到这类地区的极端危险”可知，文段表达这类地区很危险，不能盲目出发，C项“好奇”指对自己不了解的事物觉得新奇而感兴趣，能体现促使人们盲目进发的情绪，与文意相符，当选。<br>故正确答案为C。<br>【文段出处】《不得擅自进入“无人区”，青海这个提醒为何必要？|新京报快评》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":16,"pid":"pc62258248f"},{"qid":"13504378","no":8,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>大自然的雄性和小部分雌性动物在性竞争中会采取<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的手段，比如“控制资源”“使用武器”，以及进化出更有<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的形态或功能（表型）等。而推动雄性表型性进化的动力，是雌性作为选择者凭借其感官系统和大脑机制的结合在选择配偶的过程中表现出来的性审美。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"匪夷所思  亲和力"},{"k":"B","t":"行之有效  攻击性"},{"k":"C","t":"独出心裁  独特性"},{"k":"D","t":"多种多样  吸引力"}],"answer":"D","multi":false,"explanation":"<p>本题可从第二空入手，根据“是雌性作为选择者凭借其感官系统和大脑机制的结合在选择配偶的过程中表现出来的性审美”可知，雄性所进化出的形态或功能（表型）符合雌性审美，且能吸引雌性，故横线处所填词语需体现吸引之意，A项“亲和力”比喻使人感到融洽、亲切并愿意接近的力量，D项“吸引力”指能吸引别的事物、人或人的兴趣的性质或能力，均符合文意，保留。B项“攻击性”指具有对他人有意挑衅、侵犯或对事物有意损毁、破坏等心理倾向和行为的人格特征，C项“独特性”指某物或某人所具有的区别于其他同类事物的特性，均与文意不符，排除。<br>第一空，横线后通过“比如”对前文进行举例分析，根据“‘控制资源’‘使用武器’，以及进化出更有······的形态或功能（表型）等”可知，横线处所填成语应体现出大自然的雄性和小部分雌性动物在性竞争中会采取多种手段之意，D项“多种多样”指多方面的、五花八门，符合文意，当选。A项“匪夷所思”指事物怪异或人的言行离奇，不是一般人按照常理所能想象的，文段并无怪异、离奇之意，排除。<br>故正确答案为D。<br>【文段出处】中国科学报《它们的审美是异性进化的动力》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":17,"pid":"pc62258248f"},{"qid":"13504264","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>未来，金融机构应该如何进一步做好科技金融服务？ 要根据高技术产业研发投入大、周期长、风险高等特点，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>创新信贷服务模式，最大限度提高信贷服务的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，通过规范发展“贷款+外部直投”、科技保险、科技领军企业供应链金融等专属金融服务，全方位畅通高新技术企业的贷款通道。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"因势利导 适配性"},{"k":"B","t":"量身定制 特殊性"},{"k":"C","t":"兼收并蓄 积极性"},{"k":"D","t":"固本强基 重要性"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“要根据高技术产业研发投入大、周期长、风险高等特点” 可知，横线处所填成语应体现根据高技术产业的特点去创新信贷服务模式之意。A项“因势利导”指顺着事情的发展趋势加以引导，B项“量身定制”指根据功能需要定制产品，均符合文意，保留。C项“兼收并蓄”指把不同内容、不同性质的东西收下来，侧重“包容性”，D项“固本强基”指加固本体、强化基础，均与文意无关，排除。<br>第二空，搭配“信贷服务”，结合后文“通过规范发展‘贷款+外部直投’、科技保险、科技领军企业供应链金融等专属金融服务，全方位畅通高新技术企业的贷款通道”可知，横线处所填词语应体现信贷服务要与高技术产业贷款需求相匹配。A项“适配性”指互相匹配，相互适应，符合文意，当选。B项“特殊性”强调不同于一般，“最大限度提升特殊性”表述程度过重，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】经济日报 《精准做好科技金融服务》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":18,"pid":"pc62258248f"},{"qid":"13504375","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>发展新质生产力需要传统产业的支撑与贡献。发展好传统产业，可以稳住经济的基本盘，避免<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，为产业转型提供回旋空间，为新产业培育积累产业基础。因此，发展新质生产力不能不立先破、盲目放弃或忽视传统产业，也不能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，盲目上马所谓的高新技术产业。<br>依次填入画横线部分最恰当的一项是:</p>","options":[{"k":"A","t":"随波逐流 人云亦云"},{"k":"B","t":"大开大合 瞎子摸象"},{"k":"C","t":"无的放矢 朝秦暮楚"},{"k":"D","t":"大起大落 一哄而上"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“发展好传统产业，可以稳住经济的基本盘，避免······”可知，横线处所填成语应与“稳住”意思相反，体现不稳定、波动大之意，D项“大起大落”指大幅度的起与落，形容变化大，可体现“不稳定”之意，符合文意，保留。A项“随波逐流”比喻自己没有立场和主见，只是随着潮流走，B项“大开大合”形容文思跌荡，放得开，收得拢，C项“无的放矢”比喻说话做事没有明确目的，或不切合实际，均与文意不符，排除。<br>第二空，代入验证。根据“盲目上马所谓的高新技术产业”可知，横线处所填成语应形容“盲目上马”这一行为，D项“一哄而上”比喻做事没有计划、没有组织，大家乱糟糟地开始上马，符合文意，当选。<br>故正确答案为D。<br>【文段出处】光明网-文摘报《全国统一大市场建设有助于处理好三对关系》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":19,"pid":"pc62258248f"},{"qid":"13504283","no":11,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>武器因人类生存需要而产生，最初的武器来自自然的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。参照蚌壳边缘、石块边棱等尖锐、锋利的存在，人类学会了制作第一批原始武器。基于对弹性、惯性、杠杆原理等概念的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>认识，人类学会了制作弓弩、抛石机等弹射武器，极大地扩展了武器的攻击<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"馈赠 粗浅 手段"},{"k":"B","t":"启发 模糊 距离"},{"k":"C","t":"效法 初步 范围"},{"k":"D","t":"模仿 清醒 强度"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“参照蚌壳边缘、石块边棱等尖锐、锋利的存在”可知，横线处所填词语应体现因为自然而学会制作武器之意，B项“启发”指用事例引起对方联想并有所了解、领悟，符合文意，保留。A项“馈赠”指赠送，文段强调人类从自然现象中主动学习制作武器，而非被动给予，与文意不符，排除；C项“效法”指仿照别人的做法去做，学习别人的长处，D项“模仿”指照某种现成的样子学着做，置于此处应表述为“对自然的效法/模仿”，用法均错误，排除。<br>第二空，代入验证，根据“人类学会了制作弓弩、抛石机等弹射武器”可知，人类处于制作弹射武器的阶段，横线处要表达人类对科学原理的认知不深入之意，B项“模糊”指不清楚、不分明，与文意相符，保留。<br>第三空，代入验证，搭配“扩展”，且根据“弓弩、抛石机等弹射武器”可知，横线处要表达出弹射武器可以攻击更远的目标，B项“距离”指事物在空间或时间上相隔，符合文意，且搭配恰当，当选。<br>故正确答案为B。<br>【文段出处】物理《古代武器中的物理学》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":20,"pid":"pc62258248f"},{"qid":"13504280","no":12,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>面对疑难杂症，临床医学上很多时候只能摸着石头过河。在这方面，AI可以发挥很大作用。它能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>影像、病理、基因等多模态数据，提供多尺度综合分析，帮助我们构建更<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的肿瘤画像。肿瘤是一个由复杂癌细胞组成的生态系统，对其画像勾勒得越<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，就越能发现以往忽视的肿瘤行为和潜在治疗靶点，为前端治疗提供新思路。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"整合 完整 准确"},{"k":"B","t":"收集 稳定 详尽"},{"k":"C","t":"模拟 具象 立体"},{"k":"D","t":"回溯 精细 透彻"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“提供多尺度综合分析”可知，此处体现AI能获取多种数据，对多种数据进行处理，从而提供多尺度综合分析之意，A项“整合”指把零散的东西彼此衔接，从而实现信息系统的资源共享和协同工作，形成有价值有效率的一个整体，B项“收集”指使聚集在一起，均可体现获取或处理多种数据之意，保留。C项“模拟”指对真实事物或者过程的虚拟，侧重于模仿虚拟，D项“回溯”指上溯，向上推导，向内推导，侧重于推导，回忆，均不符获取或处理多种数据之意，排除。<br>第二空，搭配“肿瘤画像”，结合“提供多尺度综合分析”可知，此处体现构建更为全面的肿瘤画像之意，A项“完整”指具有或保持着应有的部分，没有损坏或残缺，可与“肿瘤画像“搭配，且可体现较为全面的肿瘤画像之意，保留。B项“稳定”指稳恒固定；没有变动；使稳定，与“肿瘤画像”搭配不当，且意思为稳定不变，不符合文意，排除。<br>第三空，代入A项验证，“准确”指行动的结果完全符合实际或预期，可对应后文“就越能发现以往忽视的肿瘤行为和潜在治疗靶点”，可体现对画像勾勒的正确性，当选。<br>故正确答案为A。<br>【文段出处】《AI如何助力重塑肿瘤诊疗模式》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"pc62258248f"},{"qid":"13504314","no":13,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>在发展流变中，汉语的表达效率不断提升。比如，“枯藤老树昏鸦，小桥流水人家，古道西风瘦马”，三个短句，省去了一切连接、修饰，全由名词并列而成。高度<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的表达下，九种景物看似独立存在，实则互相<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、有机相融，构建出一幅萧瑟秋景，游子离家、悲秋之情<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"简练 叠加 呼之欲出"},{"k":"B","t":"简约 呼应 显而易见"},{"k":"C","t":"概括 关联 不言而喻"},{"k":"D","t":"凝练 照应 溢于言表"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“省去了一切连接、修饰”可知，横线处所填词语应体现表达方式非常精炼，没有多余内容之意。A项“简练”指简明精练，B项“简约”指简略，D项“凝练”指紧凑简练，均符合文意，保留。C项“概括”指把事物的共同特点归结在一起加以简明地叙述，侧重对复杂内容进行归纳总结，与文意不符，排除。<br>第二空，根据“有机相融，构建出一幅萧瑟秋景”可知，横线处所填词语应表明景物之间彼此联系，形成一个有机的整体，B项“呼应”指互相照应，D项“照应”指对照呼应，均可体现互相存在联系，符合文意，保留。A项“叠加”指的是使预先成并存储的图形、属性特征等被调用并叠合在一个基本图形上的过程或方法，强调物理性的机械堆砌，无法体现出景物之间的内在联系，与文意不符，排除。<br>第三空，搭配“游子离家、悲秋之情”，且根据“构建出一幅萧瑟秋景，游子离家、悲秋之情”可知，横线处所填成语应体现出文字所想表达的情感非常深切之意，D项“溢于言表”意为超出言语以外，指某种思想感情虽未说明却能使人体会出来，符合文意，当选。B项“显而易见”意为事情或道理很明显，极容易看清，一般用来形容事情、道理等比较直观，容易被察觉，与“游子离家、悲秋之情”搭配不当，且“游子离家、悲秋之情”是通过对景物的描写委婉地表达出来的，并非是那种一眼就能看清楚的，置于此处不如D项更符合文意，排除。<br>故正确答案为D。<br>【文段出处】人民日报《汉语的魅力从何而来》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"pc62258248f"},{"qid":"13504332","no":14,"type":"片段阅读","module":"言语理解与表达","stem":"<p>雅文化是一种自觉的、表现为典籍形态的思想体系，流行于知识层次较高的阶层，对社会的影响深刻而狭窄。俗文化以世俗生活为中心，是民众自发的、无意识的文化心理，对社会的影响肤浅而广泛。二者之间只有形式上的自觉思想体系与民众直观体认，典籍形态与世俗传承的区别，实际上雅中有俗、俗中有雅，由俗到雅、由雅到俗。《论语》《孟子》中的语录不仅记载于典籍，也被世俗传诵。《诗经》原本是当时的民谣俚曲，后世竟成为儒家的经典。<br>这段文字意在强调雅文化与俗文化：</p>","options":[{"k":"A","t":"彼此完全对立"},{"k":"B","t":"表现形式有别"},{"k":"C","t":"社会影响不同"},{"k":"D","t":"存在互动关系"}],"answer":"D","multi":false,"explanation":"<p>文段首先引入了“雅文化”和“俗文化”的话题，并介绍了二者各自的特点，接着指出二者之间只有形式上的区别，后文通过“实际上”进行转折，强调雅中有俗、俗中有雅，由俗到雅、由雅到俗，最后通过《论语》《孟子》《诗经》进行举例论证，故文段重点在转折之后，强调雅中有俗、俗中有雅，由俗到雅、由雅到俗，D项“存在互动关系”是对文段中心的同义替换，当选。<br>A项，“彼此完全对立”文段并未涉及，无中生有，排除；<br>B项，“表现形式有别”对应文段转折之前的内容，非重点，排除；<br>C项，“社会影响不同”为文段开篇引入话题的部分，非重点，排除。<br>故正确答案为D。<br>【文段出处】光明网《社会风俗中的道德力量》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"pc62258248f"},{"qid":"13504383","no":15,"type":"片段阅读","module":"言语理解与表达","stem":"<p>从传播史上来讲，人类的传播形式经历过人际交往的口头传播。在这个阶段，由于传播主体的时空局限，文化传播特别缓慢，其中的文化是歌乐舞一体的，人可以说是“混沌的人”。文字发明之后的书写传播，扩大了空间范围、延伸了时间长度，随之诞生了一种具有反思精神和思想反刍意味的“深度的人”。古登堡革命之后是大规模印刷时代的到来，新闻报刊与20世纪以来的广播、电影视等共同将人类带入了大众传播时代。这种传播模式下，它的受众是一种“无个性的人”。这是一个由小众到大众的发展历程，也是一种人的演变过程。<br>这段文字主要介绍了：</p>","options":[{"k":"A","t":"人类传播形式的演变历史"},{"k":"B","t":"技术进步对人类传播形式的影响"},{"k":"C","t":"人从“混沌”变为“深度”的过程"},{"k":"D","t":"人类感知世界和认识社会方式的进化"}],"answer":"D","multi":false,"explanation":"<p>文段开篇从传播史视角切入，详细阐述了人类传播形式演变对人类自身感知的影响，即口头传播时期，受时空局限，人类处于“混沌的人”；书写传播时期，因时空扩展，使人们反思和思想反刍成为可能，认知方式得以深化，成为“深度的人”；大众传播时代，人们成为“无个性的人”。尾句通过指代词“这”对前文内容进行了总结，即人类在传播形式发展过程中，自身的认知也在演变。故文段重点强调人类自身感知的演变，对应D项。<br>A项，仅提及传播形式的改变，而未提及人自身的演变，偏离文段结论的重点，排除；<br>B项，文段并非强调“技术进步的影响”，而是“人类自身感知的演变”，偏离文段重点，排除；<br>C项，从“混沌”变为“深度”，仅涉及“从口头传播到书写传播”过程中的部分内容，未包括大众传播时代这些“无个性的人”，概括的不够全面，排除。<br>故正确答案为D。<br>【文段出处】光明日报《网络生态下对文学走向的展望》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"pc62258248f"},{"qid":"13504344","no":16,"type":"语句表达","module":"言语理解与表达","stem":"<p>枯木是自然界中凋枯衰朽之木的总称，宋诗中展现出各种枯木之姿，不仅丰富了诗歌的审美内蕴，还折射出宋人独特的精神追求。<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。宋代社会掀起一股尚“枯”趣味的审美潮流。在日常生活领域，“三苏”开创了清供枯木假山的潮流，枯态花卉、寒山枯林受到士人们的欣赏；在艺术创作领域，士人们在书画创作中运用枯笔技法、追崇枯瘦书体，开创了枯木题材的绘画；在诗歌批评领域，宋代出现了“枯淡”“枯劲”等一系列含“枯”的诗论概念。从日常生活到文学艺术，“枯”成为宋人的重要美学命题。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"枯木意象寄托了宋人丰富的情思意蕴"},{"k":"B","t":"对枯木的思考映现出艺术家的创作情感"},{"k":"C","t":"枯木意象与宋代社会的审美文化息息相关"},{"k":"D","t":"诗歌中的枯木意象具有深邃的思想文化内涵"}],"answer":"C","multi":false,"explanation":"<p>横线出现在文段中间，需结合前后文进行分析。横线前通过下定义的方式引出“枯木”的话题，并指出宋诗中的枯木之姿丰富了诗歌的审美内蕴，折射出宋人的精神追求。横线后从日常生活、艺术创作和诗歌批评三个角度阐述宋代社会掀起尚“枯”趣味的审美潮流，强调“枯”成为宋人重要的美学命题，故横线处应承上启下，体现“枯木”意象与宋代社会审美潮流之间的关系，对应C项。<br>A项，“情思意蕴”指情感内涵，与横线后体现的宋代尚“枯”审美潮流话题不一致，无法构成衔接，排除；<br>B项，“艺术家的创作情感”仅能对应后文的艺术创作领域，表述片面，排除；<br>D项，“具有深邃的思想文化内涵”无法体现“枯”的意象与宋代社会审美文化的关联，与后文衔接不当，排除。<br>故正确答案为C。<br>【文段出处】掌桥科研《宋诗枯木意象研究》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"pc62258248f"},{"qid":"13504339","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>水墨作为民族文化的重要象征，是历代国人观察和表现世界的一种独特方式。有别于传统绘画，当代水墨更为贴近这个时代，有着对艺术更为深入的思考。当代水墨艺术家更注重反映当下人的生存状态和精神指向，他们既了悟中国传统文化的艺术灵蕴，又深谙西方先锋艺术语言，同时兼具人文关怀和独立品格，其作品往往能够从传统中汲取精华，又能在西方美学中吸收养分，进而创造出一种新的当代语言，形成自己特有的笔墨方式来表达艺术理想，具有鲜活的时代特征和生命力量。<br>这段文字主要介绍了：</p>","options":[{"k":"A","t":"传统水墨与当代水墨之间的差异"},{"k":"B","t":"水墨作为民族文化象征的重要地位"},{"k":"C","t":"当代水墨艺术家及其作品的独特造诣"},{"k":"D","t":"水墨艺术折射出的人文关怀和文化精华"}],"answer":"C","multi":false,"explanation":"<p>文段开篇引出“水墨”的话题，接着指出“当代水墨”更贴近时代且有更深入的艺术思考。随后阐述“当代水墨艺术家”更注重反映当下人的生存状态与精神指向，他们有其自身的优势，进而强调他们的作品能从传统和西方美学中汲取养分，创造新语言、形成独特笔墨方式来表达艺术理想，具有鲜活时代特征和生命力量。故文段主题词为“当代水墨艺术家”，重点讨论当代水墨艺术家及其作品的特点，对应C项。<br>A项，“传统水墨”为引出主题词“当代水墨艺术家”的铺垫，非重点，排除；<br>B项，“水墨的重要地位”为开篇引入部分，非重点，排除；<br>D项，“水墨艺术折射出的人文关怀和文化精华”为当代水墨艺术家及其作品的具体特点，未重点突出“当代水墨艺术家”，偏离文段重点，排除。<br>故正确答案为C。<br>【文段出处】雅昌新闻《贾廷峰：当代水墨是未来艺术投资的潜力股》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"pc62258248f"},{"qid":"13504338","no":18,"type":"语句表达","module":"言语理解与表达","stem":"<p>①地球科学在寻找、开发和利用自然资源中起着巨大作用<br>②还可以帮助人类与自然环境和谐共处<br>③从应用性上来看，它为人类如何利用、保护自然提供了科学的方法论<br>④并通过掌握自然灾害的规律与其作斗争<br>⑤从理论性上来说，它承担着揭示自然界奥秘与规律的使命<br>⑥地球科学是一门理论性、应用性都很强的自然科学<br>将以上6个句子重新排列，语序正确的一项是：</p>","options":[{"k":"A","t":"⑥⑤③①②④"},{"k":"B","t":"⑥③⑤①④②"},{"k":"C","t":"①②④⑥③⑤"},{"k":"D","t":"①④②⑥③⑤"}],"answer":"A","multi":false,"explanation":"<p>对比选项，确定首句。⑥句通过下定义的方式引出“地球科学”的话题，①句介绍地球科学的巨大作用，根据行文逻辑，应先下定义引出话题再描述具体作用，因此⑥句更适合作首句，排除C、D两项。<br>对比A、B两项，⑥句后所接句子分别为⑤句和③句。③句从“应用性”的角度对地球科学进行解释，⑤句从“理论性”的角度对地球科学进行解释，根据⑥句中“地球科学是一门理论性、应用性都很强的自然科学”可知，应先说“理论性”，再介绍“应用性”，故⑤句应在③句之前，排除B项，锁定A项。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"pc62258248f"},{"qid":"13504360","no":19,"type":"语句表达","module":"言语理解与表达","stem":"<p>①研究方法是指在研究中发现新现象、新事物，或提出新理论、新观点，揭示事物内在规律的工具和手段，是论文中不可或缺的部分<br>②学习了一种方法就相当于掌握了解决某一特定问题的一件工具，掌握的工具越多，解决问题的方法越多，研究能力也就越强<br>③“工欲善其事，必先利其器”，如果“事”属于学术研究，“器”便是研究方法<br>④在论文写作过程中，研究方法是十分重要的部分，撰写论文不仅要规范格式，写好综述，尤其还要掌握常用的研究方法<br>⑤能否做好学术研究，取决于是否使用了正确的、合适的研究方法<br>⑥它解释了研究如何进行以及数据来源、数据收集技术的使用等问题<br>将以上6个句子重新排列，语序正确的一项是：</p>","options":[{"k":"A","t":"①③⑤②④⑥"},{"k":"B","t":"②③①⑤⑥④"},{"k":"C","t":"③①④⑥②⑤"},{"k":"D","t":"④⑤①⑥③②"}],"answer":"D","multi":false,"explanation":"<p>观察选项，判断首句。①句介绍研究方法是什么，并指出其对论文的重要性，②句介绍学习、掌握研究方法后带来的意义，③句指出“器”是研究方法，④句通过“尤其”强调研究方法对论文的重要性，①句、③句和④句均可以引出“研究方法”这一话题，按照逻辑顺序，应先引出“研究方法”的话题，再介绍掌握研究方法之后的意义，故②句应该放在①③④三句之后，排除A、B两项。<br>继续观察发现，⑥句出现指代词“它”，可以考虑通过指代词捆绑解题。对比④⑥句、①⑥句，①句具体介绍研究方法的定义，指出研究方法是发现新现象，揭示事物内在规律的工具，⑥句中“研究如何进行以及数据来源、数据收集技术的使用”是对研究方法是论文写作工具的进一步说明，话题一致且内容衔接得当，④句指出在论文写作过程中要掌握常用的研究方法，与⑥句内容无法衔接，排除C项。<br>故正确答案为D。<br>【文段出处】微信公众号北体新传《2023年体育新闻传播研究方法与论文写作工作坊》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"pc62258248f"},{"qid":"13504348","no":20,"type":"片段阅读","module":"言语理解与表达","stem":"<p>传统文博展示方式受场地空间、展览时间、文物特性等因素影响，限制了传播力与影响力的进一步提升，很难满足海量游人参观体验的需求。为此，可善用人工智能、虚拟现实等先进技术，推动文博展陈与文创产品数字化、沉浸式转化。比如，近期成立的全国博物馆文创联盟、博物馆策展联盟等平台，正以创新方式探索文博行业发展的新路径，带动中小型博物馆深度挖掘文物背后的故事，并运用新技术打破时空壁垒，以数字化方式让万千文博展品走进大众生活。<br>这段文字意在说明，文博展陈应：</p>","options":[{"k":"A","t":"拓展多空间，善用新技术"},{"k":"B","t":"活化老文物，挖掘新共鸣"},{"k":"C","t":"传承古智慧，融合新媒体"},{"k":"D","t":"展现历史美，利用新视角"}],"answer":"A","multi":false,"explanation":"<p>文段首先指出传统文博展示方式难以满足游人参观体验需求的问题，接着通过“为此”提出善用先进技术推动文博展陈与文创产品数字化、沉浸式转化这一对策，最后通过“比如”进行举例论证，故文段重点强调“为此”之后的对策，即善用先进技术推动文博展陈的发展，A项能够体现文段重点“善用先进技术”，当选。<br>B项“新共鸣”、C项“新媒体”、D项“新视角”均偏离主题词“先进技术”，排除。<br>故正确答案为A。<br>【文段出处】中国经济网《展创结合让文物活起来》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"pc62258248f"},{"qid":"13504362","no":21,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在机场过安检时，有时会遇到这样的情景：安检人员用一张白色的小纸片在你的手提行李、电子设备，甚至你的衣服上擦拭一遍，再将试纸放入一旁的仪器中。这张白色的小纸片其实是一种专门设计的爆炸物痕量检测纸，用于探测行李或物品表面是否残留有爆炸物的痕迹。它的使用起源于对航空安全的严格要求，尤其是在现代航空业面对的恐怖主义威胁日益增多的背景下，痕量检测技术已成为机场安检系统中的重要组成部分。<br>这段文字接下来最不可能谈及的是：</p>","options":[{"k":"A","t":"爆炸物痕量检测纸的工作原理"},{"k":"B","t":"安检中使用痕量检测纸的利弊"},{"k":"C","t":"机场采用痕量检测技术的背景"},{"k":"D","t":"候机楼发现爆炸物的处置程序"}],"answer":"D","multi":false,"explanation":"<p>本题为接语选择题，需通读全文，重点把握文段最后讨论的核心话题。文段开篇描述机场安检人员使用爆炸物痕量检测纸的情景，接着介绍其用途、使用起源，最后强调痕量检测技术在机场安检系统的重要性。故文段接下来应重点围绕痕量检测技术在安检中的相关内容展开。<br>A项，文段描述了痕量检测纸的用途，但并未深入解释其工作原理，此项与文段话题紧密相关，排除；<br>B项，文段探讨了痕量检测技术的重要性，但并未提及其弊端，探讨其利弊是合理延伸，排除；<br>C项，“机场采用痕量检测技术的背景”与尾句“背景”相关，接下来有可能展开探讨，排除；<br>D项，与文段最后谈论的核心话题不符，接下来最不可能谈及，当选。<br>本题为选非题，故正确答案为D。<br>【文段出处】科普中国《坐飞机过安检时擦的小纸片是什么？》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":30,"pid":"pc62258248f"},{"qid":"13504343","no":22,"type":"语句表达","module":"言语理解与表达","stem":"<p>郑和大航海发生在中国军事科技实力遥遥领先的背景下，郑和率领两百余艘船、两万多名将士的大舰队，实力远超大航海时代两三艘船、百余人的小船队，军事实力更是远超途经的国家和地区，但郑和船队坚持“共享太平之福”“敦睦邦交”“强不凌弱”的原则，奉行“厚往薄来”的政策，从来没有以大欺小，倚强凌弱，没有掠夺一两黄金白银，没有发动一场军事侵略，也没有占领一寸海外殖民地。“郑和大航海”<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"在中外交流交往中发挥了积极的作用"},{"k":"B","t":"为中国的发展创造了稳定的国际环境"},{"k":"C","t":"是中华民族一脉相承的和平基因的最好例证"},{"k":"D","t":"为推动构建海洋命运共同体提供了中国方案"}],"answer":"C","multi":false,"explanation":"<p>横线位于文段结尾，需结合前文内容进行分析。文段开篇点明郑和大航海所处背景是中国军事科技实力遥遥领先的时候，郑和船队实力远超同时代其他船队。随后通过转折词“但”指出郑和船队始终秉持“共享太平之福”“敦睦邦交”“强不凌弱”的原则，奉行“厚往薄来”的政策，在航海过程中未进行掠夺、侵略和占领。这些行为充分彰显了和平友好的特质。故文段最后应进行总结，表明“郑和大航海”所展现的和平理念，对应C项。<br>A项，“在中外交流交往中发挥了积极的作用”偏离文段核心话题，文段重点强调的是郑和大航海过程中展现的和平理念，而非其在中外交流交往中的积极作用，排除；<br>B项，“为中国的发展创造了稳定的国际环境”无中生有，文段并没有表明中国因郑和大航海而获得了怎样稳定的国际环境，排除；<br>D项，“海洋命运共同体”是现代概念，文段围绕的是郑和大航海时期的和平行为，与文段时代背景不符，排除。<br>故正确答案为C。<br>【文段出处】光明网《向世界讲好“郑和大航海”故事》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":31,"pid":"pc62258248f"},{"qid":"13504325","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>免疫系统包含三大防线，皮肤、黏膜作为免疫系统的第一道防线，会阻止所有病毒或细菌的进入。当病毒或细菌已经侵入到人的身体时，巨噬细胞率先开始发挥作用。巨噬细胞能把外来异物如病毒或细菌吞入，靠内部的酶和各种活性物质杀死它们或者使其降解。当侵入人体的病毒或细菌数量过大时，巨噬细胞会释放化学信号，这时免疫系统的“保安”——白细胞能通过变形而穿过毛细血管壁，聚集到病菌入侵部位，将其包围、吞噬。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"巨噬细胞的工作机制"},{"k":"B","t":"免疫系统如何抵御病菌"},{"k":"C","t":"白细胞具有包围、吞噬病菌的作用"},{"k":"D","t":"皮肤、黏膜是免疫系统的第一道防线"}],"answer":"B","multi":false,"explanation":"<p>文段开篇介绍免疫系统有三大防线，接着论述第一道防线会阻止所有病毒或细菌的进入，之后指出当病毒或细菌侵入人体后，巨噬细胞先开始发挥作用，最后论述当侵入人体的病毒或细菌数量过大时，白细胞会将病菌包围和吞噬，故文段为三方面的并列结构，详细介绍了免疫系统抵御病菌的三道防线，对应B项。<br>A项“巨噬细胞”、C项“白细胞”和D项“皮肤、黏膜”均为文段并列的一部分内容，表述片面，排除。<br>故正确答案为B。<br>【文段出处】光明日报《免疫系统是如何抵御病毒的》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":32,"pid":"pc62258248f"},{"qid":"13504342","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>农耕时代生产与生活、人与自然的关系十分密切。人们或为了感恩大自然的恩赐，或为了庆祝辛苦劳作换来的收获，或为了激发生命的活力，或为了加强人际的亲情，经过长期相互认同，最终约定俗成，渐渐把一年中某一天确定为节日，并创造了十分完整又严格的节俗，如仪式、庆典、规制、禁忌，乃至特定的游艺、装饰与食品，来把节日这天演化成一个内涵独特、氛围迷人的日子。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"节日的内涵"},{"k":"B","t":"节日的形成"},{"k":"C","t":"节俗的意义"},{"k":"D","t":"节俗的创造"}],"answer":"B","multi":false,"explanation":"<p>文段开篇介绍农耕时代生产与生活、人和自然关系密切，随后指出人们因感恩自然、庆祝收获等原因，经过长期相互认同，最终约定俗成将一年中的某一天定为节日，后文举例说明节日中的一些习俗，并指出节俗让节日更有内涵和氛围，故文段重在说明节日是如何形成的，对应B项。<br>A项，“节日的内涵”文段并未提及，无中生有，排除；<br>C项，文段重点强调节日的形成，“节俗的意义”非重点，排除；<br>D项，“节俗的创造”仅为节日形成过程中的一部分，表述片面，排除。<br>故正确答案为B。<br>【文段出处】天津市老教授协会《冯骥才：我们为什么要过节》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":33,"pid":"pc62258248f"},{"qid":"13504352","no":25,"type":"片段阅读","module":"言语理解与表达","stem":"<p>近年来，相关地区依托长城保护修复实践基地，将长城保护工作重心由一般性保护工程向研究性修缮项目转变。与以往修缮过程中各专业技术人员作业相对分离不同，研究性修缮从工程启动便形成协同模式：以考古挖掘为开端，多学科研究为手段，数字化跟踪记录为保障，考古、设计、勘察、施工等人员在前期研究与勘察、设计方案制定、施工执行、成果整理等各环节协同配合，形成全专业全周期的合作。<br>最适合做这段文字标题的是：</p>","options":[{"k":"A","t":"研究性修缮：考古保护新范式"},{"k":"B","t":"研究性修缮如何进行多学科协同"},{"k":"C","t":"长城保护：研究性修缮的协同新模式"},{"k":"D","t":"研究性修缮揭开长城科学保护的细节"}],"answer":"C","multi":false,"explanation":"<p>文段开篇介绍长城保护工作重心由一般性保护工程向研究性修缮项目转变，接着指出与以往的修缮过程不同，研究性修缮项目注重形成协同模式，后文具体描述协同的各个环节，故文段重在强调研究性修缮项目注重以协同模式开展长城保护工作，对应C项。<br>A项，“考古保护”范围扩大，文段强调的是“长城保护”，排除；<br>B项，未包含主题词“长城保护”，排除；<br>D项，偏离文段核心话题“协同模式”，且“长城科学保护的细节”无中生有，排除。<br>故正确答案为C。<br>【文段出处】人民日报《研究性修缮助力长城保护（新知）》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":34,"pid":"pc62258248f"},{"qid":"13504326","no":26,"type":"片段阅读","module":"言语理解与表达","stem":"<p>西北太平洋台风主要形成于菲律宾以东的西北太平洋海域。这片海域全年温暖湿润，尤其是在夏季和秋季，海水温度升高，空气湿度加大，为台风的生成提供了充足能量。因此，西北太平洋成为全球台风生成最为活跃的区域之一。通常情况下，西北太平洋台风生成后沿西北方向移动，逐步影响中国、菲律宾、日本等国家。相比之下，南海被众多岛屿和大陆环抱，为台风活动提供了一个独特的舞台。由于位于热带和副热带气候带之间，南海夏季海温同样较高，这为台风的生成提供了充足的能量。而季风活动对南海台风的生成和发展有重要影响，使其具有明显的季节性和区域性特点。<br>这段文字未提及的是：</p>","options":[{"k":"A","t":"西北太平洋台风的影响范围"},{"k":"B","t":"南海台风与季风活动的关系"},{"k":"C","t":"南海台风的路径变化特点"},{"k":"D","t":"地形在台风形成中的作用"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“通常情况下，西北太平洋台风生成后沿西北方向移动，逐步影响中国、菲律宾、日本等国家”可知，“影响范围”有所提及，排除；<br>B项，根据“而季风活动对南海台风的生成和发展有重要影响，使其具有明显的季节性和区域性特点”可知，“南海台风与季风活动的关系”有所提及，排除；<br>C项，文段中并未提及南海台风的路径变化特点，无中生有，当选；<br>D项，根据“南海被众多岛屿和大陆环抱，为台风活动提供了一个独特的舞台”可知，“地形在台风形成中的作用”有所提及，排除。<br>本题为选非题，故正确答案为C。<br>【文段出处】中国气象报社《生于海上，几多风雨？——谈谈台风的认知误区》</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":35,"pid":"pc62258248f"},{"qid":"13504534","no":1,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性。</p><p><img src=\"assets/img/timu/19599f24f228d13.png\" class=\"fig\" style=\"width:600px;height:271px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成不同，优先考虑属性规律。观察发现，题干已知图形的黑块均为轴对称图形，且都只有一条对称轴，而D项的黑块有两条对称轴，排除；继续观察发现，题干已知图形中都只有一个轴对称的空白面，该空白面也只有一条对称轴，且该空白面的对称轴与所在图形中黑块的对称轴从左到右依次呈垂直、平行位置关系交替，故？处图形黑块的对称轴与轴对称空白面的对称轴应为平行关系，只有A项符合。</p><p><img src=\"assets/img/timu/19599f449b62536.png\" class=\"fig\" style=\"width:600px;height:271px;\"></p><p>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":36,"pid":"pc62258248f"},{"qid":"13504268","no":2,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</p><p><img src=\"assets/img/timu/19598906628b543.png\" class=\"fig\" style=\"width:600px;height:261px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形均由黑白球组成，第一组图形黑球每次增加1个，白球每次增加2个；第二组图形黑球每次增加2个，白球每次增加1个，故？处图形应该包含6个黑球、3个白球，排除A、B两项；再次观察发现，题干图形都是由不同颜色的球组成，且明显分为内外两圈，考虑分开看。第一组图中，内圈的黑球依次顺时针增加1个，外圈的白球依次逆时针增加2个；第二组图中，前两幅图内圈的白球依次顺时针增加1个，外圈的两部分黑球各依次逆时针增加1个，？处图形应用此规律，只有D项符合。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":37,"pid":"pc62258248f"},{"qid":"13504266","no":3,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</p><p><img src=\"assets/img/timu/195989147f9a402.png\" class=\"fig\" style=\"width:600px;height:271px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>解析一：元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图形线条交叉明显，且每幅图均出现明显的弧线，考虑数曲直交点。曲直交点数均为1，排除B项；继续观察发现，题干图形曲直交点的特征依次为：曲线的端点与直线交叉、曲线的中段与直线“十字交叉”、曲线的端点与直线交叉、曲线的中段与直线“十字交叉”、曲线的端点与直线交叉，故？处图形的曲直交点应为曲线的中段与直线“十字交叉”，只有D项符合。<br>故正确答案为D。<br>解析二：<br>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图形线条交叉明显，且每幅图均出现明显的弧线，考虑曲直交点。曲直交点数均为1，排除B项；继续观察发现，题干图形曲直交点的特征为：曲线与直线（横线或竖线）相交、曲线与斜线相交、曲线与直线（横线或竖线）相交、曲线与斜线相交、曲线与直线（横线或竖线）相交，故？处图形的曲直交点应为曲线与斜线相交，只有A项符合。<br>故正确答案为A。<br>注：本题粉笔倾向于解析一。因为题干图形均只有一条曲线，曲线的端点或中段与直线相交的特征更明确；另外，解析二中图1为曲线与竖线相交，图3和图5为曲线与横线相交，其直线方向不完全一样。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":38,"pid":"pc62258248f"},{"qid":"13504539","no":4,"type":"图形推理","module":"判断推理","stem":"<p>下图为给定的多面体，将其沿a、b、c三个顶点所在的平面切开，其截面是（    ）。</p><p><img src=\"assets/img/timu/19599f4c9c221d2.png\" class=\"fig\" style=\"width:600px;height:158px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查截面图。根据平面公理“过不在一条直线上的三点，有且只有一个平面”可以得出，经过a、b、c三点可以确定唯一的平面，即所得截面为B项，如下图所示：</p><p><img src=\"assets/img/timu/19599f5a9d36899.png\" class=\"fig\" style=\"width:250px;height:206px;\"></p><p>故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":39,"pid":"pc62258248f"},{"qid":"13504389","no":5,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/195995551539412.png\" class=\"fig\" style=\"width:500px;height:394px;\"></p>","options":[{"k":"A","t":"①③④，②⑤⑥"},{"k":"B","t":"①②④，③⑤⑥"},{"k":"C","t":"①②⑤，③④⑥"},{"k":"D","t":"①④⑥，②③⑤"}],"answer":"B","multi":false,"explanation":"<p>本题为分组分类题目。元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形被分割，考虑面数量，但面数量无规律，且框内有明显一笔构成的线条，考虑笔画数。图①②④均为两笔画图形，图③⑤⑥均为一笔画图形，即图①②④为一组，图③⑤⑥为一组。<br>故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":40,"pid":"pc62258248f"},{"qid":"13504273","no":6,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/19598921b4fb462.png\" class=\"fig\" style=\"width:500px;height:395px;\"></p>","options":[{"k":"A","t":"①③④，②⑤⑥"},{"k":"B","t":"①②④，③⑤⑥"},{"k":"C","t":"①⑤⑥，②③④"},{"k":"D","t":"①②⑥，③④⑤"}],"answer":"C","multi":false,"explanation":"<p>本题为分组分类题目。元素组成相同，但无位置规律和属性规律，考虑数量规律。观察发现，题干图形黑球和白球分堆明显，考虑部分数。图①⑤⑥中黑球部分数均为1，白球部分数均为4，图②③④中黑球部分数均为2，白球部分数均为3，故图①⑤⑥为一组，图②③④为一组。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":41,"pid":"pc62258248f"},{"qid":"12882042","no":7,"type":"图形推理","module":"判断推理","stem":"<p>下面为15个白色块和3个黑色块立体图的左视图和主视图，那么俯视图应该是（    ）。</p><p><img src=\"assets/img/timu/19675238e8dcd76.png\" class=\"fig\" style=\"width:600px;height:378px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>本题考查三视图。左视图最右列上方有1个黑色正方形，且该黑色正方形正上方为空白，则对应俯视图最下方一行中必有小黑色正方形，排除B、D两项。左视图、主视图结合选项俯视图可以确定立体图形，逐一分析A、C选项。</p><p>A项：结合题干两个视图和A项，确定立体图形如下图所示（注意底层是7个白色块），立体图形有15个白色块和3个黑色块，符合题干要求；</p><p><img src=\"assets/img/timu/196847fe5f95cf8.png\" class=\"fig\" style=\"width:162px;height:167px;\"></p><p>C项：结合题干两个视图和C项，确定立体图形如下图所示（注意底层是7个白色块），立体图形有14个白色块和3个黑色块，不符合题干要求。</p><p><img src=\"assets/img/timu/1959af8a2af3011.png\" class=\"fig\" style=\"width:159px;height:179px;\"></p><p>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":42,"pid":"pc62258248f"},{"qid":"13504533","no":8,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性。</p><p><img src=\"assets/img/timu/19599f210815d03.png\" class=\"fig\" style=\"width:600px;height:281px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。观察发现，图1与图2下侧两个白球位置没有发生变化，图2与图3左侧两个白球位置没有发生变化，图3与图4上侧两个白球位置没有发生变化，图4与图5右侧两个白球位置没有发生变化，按照此规律，图5与？处图形下侧两个白球位置应该没有发生变化，排除C、D两项；继续观察发现，每个图形中位置发生变化的两个白球在各自的框内顺时针平移1步，排除B项，只有A项符合。</p><p><img src=\"assets/img/timu/19599f33af0a8a0.png\" class=\"fig\" style=\"width:600px;height:281px;\"></p><p>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":43,"pid":"pc62258248f"},{"qid":"13504530","no":9,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性。</p><p><img src=\"assets/img/timu/19599f1b75276c7.png\" class=\"fig\" style=\"width:600px;height:279px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成相同，但无明显位置规律，考虑属性规律。观察发现，题干所有图形均由黑球和白球构成，考虑黑白球分开看，且题干图形的黑球或白球部分较为规整，考虑对称性。图1、图3、图5的黑球部分均为轴对称图形，图2、图4的白球部分均为轴对称图形，故？处图形的白球部分应为轴对称图形，排除A、B两项；继续观察发现，题干已知图形中轴对称部分的对称轴方向依次顺时针旋转<img src=\"assets/img/gongshi/formula-66d1763c3dc7ea2b.png\" class=\"tex\">，故？处图形中轴对称部分的对称轴方向应为水平，只有C项符合。</p><p><img src=\"assets/img/timu/19599f2a590924f.png\" class=\"fig\" style=\"width:632px;height:296px;\"></p><p>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":44,"pid":"pc62258248f"},{"qid":"13504308","no":10,"type":"图形推理","module":"判断推理","stem":"<p>左下图为两个正方体组合而成的长方体，这两个正方体的外表面展开图分别可能是：</p><p><img src=\"assets/img/timu/195b1a212bd95bd.png\" class=\"fig\" style=\"width:500px;height:239px;\"></p>","options":[{"k":"A","t":"①和②"},{"k":"B","t":"③和④"},{"k":"C","t":"①和④"},{"k":"D","t":"②和③"}],"answer":"A","multi":false,"explanation":"<p>将题干两个正方体的面标上字母序号，并在立体图形和外表面展开图的黑色半圆形面（面e和面g）中以黑色半圆形的直径所在的边为起始边，顺时针描边标号，如下图所示。</p><p><img src=\"assets/img/timu/1961835bf06b17b.jpg\" class=\"fig\" style=\"width:279px;height:173px;\"></p><p><img src=\"assets/img/timu/196ad7cbc8dcb50.png\" class=\"fig\" style=\"width:700px;height:195px;\"></p><p>图①中，标出黑色半圆形面中对应的边1和边4后发现，二者与题干右侧正方体中面g的边1和边4对应一致，可能是题干右侧正方体的外表面展开图。</p><p>图②中，标出黑色半圆形面与小直角三角形面的公共边（即边3）后发现，边3与题干左侧正方体中面e和面f的公共边对应一致，可能是题干左侧正方体的外表面展开图。</p><p>图③中，标出黑色半圆形面中对应的边1和边3后发现，边1与题干右侧正方体中面g的边1不对应一致，不可能是题干右侧正方体的外表面展开图；边3与题干左侧正方体中面e的边3不对应一致，不可能是题干左侧正方体的外表面展开图。故图③不可能是组成长方体的任一正方体的外表面展开图。</p><p>图④中，黑色半圆形面中对应的边1与题干右侧正方体中面g的边1不对应一致，不可能是题干右侧正方体的外表面展开图；黑色半圆形面中对应的边3与题干左侧正方体中面e的边3不对应一致，不可能是题干左侧正方体的外表面展开图。故图④不可能是组成长方体的任一正方体的外表面展开图。</p><p>综上，两个正方体的外表面展开图可能是①和②，对应A项。</p><p>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":45,"pid":"pc62258248f"},{"qid":"13504323","no":11,"type":"定义判断","module":"判断推理","stem":"<p>情绪爆发策略是指在谈判过程中，当双方在某一个问题上相持不下，或者对方的态度、行为欠妥，要求不太合理时，通过情绪爆发、大发脾气等手段有意制造僵局逼迫对方，从而使对方被迫让步的谈判策略。<br>根据上述定义，下列符合情绪爆发策略的是：</p>","options":[{"k":"A","t":"小强脾气很是暴躁，做事没有耐心，经常一遇到不顺心的事就生气发火，家里人都不敢和他亲近"},{"k":"B","t":"老王作为公司负责人经常出去谈判，有时遇到对方提出无理要求，他总会大发脾气直接离席，不再与对方谈判"},{"k":"C","t":"谈判时，双方在某原则性问题上讨论了两天毫无进展，老周率领代表团临时离席表达自己的不满，最终对方作出了让步"},{"k":"D","t":"多多与父母沟通，要求买新手机，但被父母拒绝了，多多以离家出走要挟父母必须给他买，父母坚决不同意并对他进行了批评教育"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“在谈判过程中”、“双方在某一个问题上相持不下，或者对方的态度、行为欠妥，要求不太合理”、“通过情绪爆发、大发脾气等手段有意制造僵局逼迫对方”、“使对方被迫让步”。<br>第二步：逐一分析选项。<br>A项：小强脾气很是暴躁，做事没有耐心，遇到不顺心的事就生气发火，是日常做事的态度和行为，不符合“在谈判过程中”，家里人都不敢和他亲近，不符合“使对方被迫让步”，不符合定义，排除；<br>B项：老王在谈判过程中，遇到对方提出无理要求，不再与对方谈判，直接终止谈判而不是在继续的谈判中迫使对方让步，不符合“使对方被迫让步”，不符合定义，排除；<br>C项：谈判时，双方在某原则性问题上讨论了两天毫无进展，符合“在谈判过程中”、“双方在某一个问题上相持不下”，老周率领代表团临时离席表达自己的不满，最终对方作出了让步，符合“通过情绪爆发、大发脾气等手段有意制造僵局逼迫对方”、“使对方被迫让步”，符合定义，当选；<br>D项：多多以离家出走要挟父母必须给他买手机，但父母坚决不同意并对他进行了批评教育，证明父母没有让步，不符合“使对方被迫让步”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":46,"pid":"pc62258248f"},{"qid":"13504331","no":12,"type":"定义判断","module":"判断推理","stem":"<p>主动收入就是用时间来换取金钱，它最大的特点就是必须花费时间和精力去获得，它是一种临时性收入，做一次工作得到一次回报。被动收入是不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入。<br>根据上述定义，下列各项收入中不属于被动收入的是：</p>","options":[{"k":"A","t":"银行存款的收益"},{"k":"B","t":"授权专利的许可费"},{"k":"C","t":"每月固定的兼职工资"},{"k":"D","t":"退休后每月领到的退休金"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>主动收入：“用时间来换取金钱”、“最大的特点就是必须花费时间和精力去获得”、“一种临时性收入，做一次工作得到一次回报”；<br>被动收入：“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”。<br>第二步：逐一分析选项。<br>A项：银行存款的收益无需花费额外的时间和精力，就可自动获得利息，符合“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”，符合“被动收入”定义，排除；<br>B项：授权专利的许可费无需花费额外的时间和精力，只要有人使用专利，就可获得许可费用，符合“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”，符合“被动收入”定义，排除；<br>C项：每月固定的兼职工资是需要花费时间和精力的，也是做一次工作得到一次回报，符合“用时间来换取金钱”、“最大的特点就是必须花费时间和精力去获得”、“一种临时性收入，做一次工作得到一次回报”，符合“主动收入”定义，不符合“被动收入”定义，当选；<br>D项：退休后每月领到的退休金无需花费额外的时间和精力，是按照当前的相关制度，每月自动发放的，符合“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”，符合“被动收入”定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":47,"pid":"pc62258248f"},{"qid":"13504324","no":13,"type":"定义判断","module":"判断推理","stem":"<p>文化再生产是指文化模式、信仰、价值观、习俗、语言和其他社会行为在时间上的持续性和在不同社会成员之间的传递，通常通过教育系统、家庭、媒体、宗教机构和其他社会机构来实现。这些机构通过传授知识、规范和行为模式，帮助新一代成员学习并内化其文化。<br>根据上述定义，下列一定属于文化再生产的是：</p>","options":[{"k":"A","t":"小王在单亲家庭长大，从小养成了独立的性格"},{"k":"B","t":"在公司聚会上，小李向同事介绍自己的女朋友"},{"k":"C","t":"某小学开设了具有当地特色的民俗课，深受学生喜爱"},{"k":"D","t":"电视上不断滚动播放着某品牌家用饮水设备的广告语"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“文化模式、信仰、价值观、习俗、语言和其他社会行为”、“时间上的持续性”、“不同社会成员之间的传递”。<br>第二步：逐一分析选项。<br>A项：单亲家庭中长大的小王，养成了独立的性格，性格是一个人对现实的相对稳定的态度，不符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”，养成独立的性格也不符合“不同社会成员之间的传递”，不符合定义，排除；<br>B项：小李在公司聚会上向同事们介绍自己的女朋友，传递给同事的信息是关于女朋友的基本情况，不符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”，不符合定义，排除；<br>C项：某小学开设了具有当地特色的民俗课，民俗课可以将当地特色的民间文化通过课程的形式传递给同学们，符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”、“不同社会成员之间的传递”，课程深受学生喜爱，同学们通过学习逐渐了解并认同这些民俗，有利于把当地特色民俗传承下去，符合“时间上的持续性”，符合定义，当选；<br>D项：某品牌家用饮水设备的广告语不断在电视上滚动播放，电视广告传递的是饮水设备的产品信息，不符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":48,"pid":"pc62258248f"},{"qid":"13504322","no":14,"type":"定义判断","module":"判断推理","stem":"<p>在经济学当中，运动防御是指企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域，以作为将来防御和进攻的中心。<br>根据上述定义，下列不属于运动防御的是：</p>","options":[{"k":"A","t":"某石油公司转型为能源公司，市场范围扩展到煤炭、核能、水利和化学等多方面"},{"k":"B","t":"某饮料公司发现许多人都在控制糖类摄入，于是推出了不少低糖饮料，以此来稳固市场"},{"k":"C","t":"某手机公司除了钻研提升手机性能以外，近几年还推出了智能穿戴、新能源汽车等多类产品"},{"k":"D","t":"某白酒公司认识到年轻人对白酒的消费意愿不强，于是拓展进入了冷冻食品等其他行业，实行多元化经营"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”。<br>第二步：逐一分析选项。<br>A项：石油公司将业务扩展至煤炭、核能、水利和化学等新的领域，符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，符合定义，排除；<br>B项：低糖饮料属于饮料行业的细分产品，饮料公司并未向新的领域扩展业务，不符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，不符合定义，当选；<br>C项：手机公司将业务扩展至智能穿戴、新能源汽车等新的领域，符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，符合定义，排除；<br>D项：白酒公司将业务扩展至冷冻食品等新的领域，符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，符合定义，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":49,"pid":"pc62258248f"},{"qid":"13504336","no":15,"type":"定义判断","module":"判断推理","stem":"<p>生理性购买动机是指消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机，社会性购买动机是指由社会性因素引起的消费者购买商品的动机。消费者的社会性购买动机是在后天社会因素的影响下形成的，一般可分为基本的社会性动机和高级的社会性动机。由社会交往、归属、自主等意念引起的购买动机，属于基本的社会性购买动机；由成就、威望等意念引起的购买动机，属于高级的社会性购买动机。<br>根据上述定义，下列属于社会性购买动机的是：</p>","options":[{"k":"A","t":"小乔每周都会和朋友出去约饭喝茶"},{"k":"B","t":"小华每周都会购买必要的生活物资"},{"k":"C","t":"小吴每周都会去社区参加义工活动"},{"k":"D","t":"小曼每个季度会购买刚需换季衣物"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>生理性购买动机：“消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机”；<br>社会性购买动机：“由社会性因素引起的消费者购买商品的动机”、“分为基本的社会性动机和高级的社会性动机”；<br>基本的社会性购买动机：“由社会交往、归属、自主等意念引起的购买动机”；<br>高级的社会性购买动机：“由成就、威望等意念引起的购买动机”。<br>第二步：逐一分析选项。<br>A项：小乔每周都会和朋友出去约饭喝茶，符合“由社会交往、归属、自主等意念引起的购买动机”，符合“基本的社会性购买动机”定义，也符合“社会性购买动机”定义，当选；<br>B项：小华每周都会购买必要的生活物资，符合“消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机”，符合“生理性购买动机”定义，不符合“社会性购买动机”定义，排除；<br>C项：小吴每周都会去社区参加义工活动，参加义工活动不涉及购买商品，不符合“由社会性因素引起的消费者购买商品的动机”，不符合“社会性购买动机”定义，排除；<br>D项：小曼每个季度会购买刚需换季衣物，符合“消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机”，符合“生理性购买动机”定义，不符合“社会性购买动机”定义，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":50,"pid":"pc62258248f"},{"qid":"13504350","no":16,"type":"定义判断","module":"判断推理","stem":"<p>通常把公开出版发行的文献称为白色文献，把涉及机密无法公开出版发行的文献称为黑色文献。灰色文献是指采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献。灰色文献介于白色和黑色文献之间，已经发行但不易通过一般销售渠道购得。<br>根据上述定义，下列不属于灰色文献的是：</p>","options":[{"k":"A","t":"某行业协会印刷的提供给协会会员使用的技术规范"},{"k":"B","t":"某高校文学院为召开某次学术会议印刷的会议论文集"},{"k":"C","t":"某考古学杂志社每期印刷的受众极小的专业类学术期刊"},{"k":"D","t":"某企业印刷的在其内部流通的塑造企业文化的内部刊物"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>白色文献：“公开出版发行的文献”；<br>黑色文献：“涉及机密无法公开出版发行的文献”；<br>灰色文献：“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”。<br>第二步：逐一分析选项。<br>A项：行业协会印刷的提供给协会会员使用的技术规范，是在协会的内部传播，不易通过一般销售渠道购得，符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”，符合灰色文献的定义，排除；<br>B项：高校文学院为学术会议印刷的会议论文集，只适用在学术会议这一特定场合，尚未正式出版，也不能通过一般销售渠道购得，符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”，符合灰色文献的定义，排除；<br>C项：考古学杂志社每期印刷的受众极小的学术期刊，虽然受众小，但也属于正式出版发行的文献，符合“公开出版发行的文献”，不符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”，符合白色文献的定义，不符合灰色文献的定义，当选；<br>D项：企业印刷的内部刊物只在其内部流通，并未正式出版，也不能通过一般销售渠道购得，符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”，符合灰色文献的定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":51,"pid":"pc62258248f"},{"qid":"13504341","no":17,"type":"定义判断","module":"判断推理","stem":"<p>校友经济是指在校友的社会活动中以母校为核心，通过母校与校友、校友与校友、母校与社会之间所产生的物质、文化、人才等方面的交流，从而给母校、校友以及社会带来客观收益的经济活动。校友经济以母校和校友为载体，目的是通过校友与母校之间天然的纽带，长期不断循环推动相关经济活动的发展。<br>根据上述定义，下列属于校友经济的是：</p>","options":[{"k":"A","t":"某大学校友会举办了校园招聘活动，23家校友企业出席并提供了超100个就业岗位"},{"k":"B","t":"某自媒体博主将自己赚的第一桶金捐给了贫困山区的学校，为他们购买了学习物资，助力乡村教育发展"},{"k":"C","t":"某高校给予对学校建设和发展作出突出贡献的校友精神奖励，包括但不限于授予荣誉称号，聘请担任名誉职务等"},{"k":"D","t":"某高校定期举办成功校友与在校学生座谈活动，让校友现身说法，通过典型宣传，进一步做实大学生思想政治工作"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“校友的社会活动中以母校为核心”、“以母校和校友为载体”、“给母校、校友以及社会带来客观收益的经济活动”。<br>第二步：逐一分析选项。<br>A项：校友会举办了校园招聘活动，校友企业提供了就业岗位，符合“校友的社会活动中以母校为核心”、“以母校和校友为载体”、“给母校、校友以及社会带来客观收益的经济活动”，符合定义，当选；<br>B项：某自媒体博主将自己赚的第一桶金捐给了贫困山区的学校，并没有体现母校与校友的核心主体，不符合“校友的社会活动中以母校为核心”、“以母校和校友为载体”、“给母校、校友以及社会带来客观收益的经济活动”，不符合定义，排除；<br>C项：某高校给予对学校建设和发展作出突出贡献的校友精神奖励，并未体现校友给母校带来的客观收益的经济活动，不符合“给母校、校友以及社会带来客观收益的经济活动”，不符合定义，排除；<br>D项：某高校定期举办成功校友与在校学生座谈活动，进一步做实大学生思想政治工作，属于教育引导，并没有涉及经济活动，不符合“给母校、校友以及社会带来客观收益的经济活动”，不符合定义，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":52,"pid":"pc62258248f"},{"qid":"13504346","no":18,"type":"定义判断","module":"判断推理","stem":"<p>在管理心理学中，人们把在不记姓名或相互不了解的情况下个体独立性、自主性得到充分体现的现象，称之为匿名效应。<br>根据上述定义，下列属于匿名效应的是：</p>","options":[{"k":"A","t":"小刘到了一个新成立的公司，大家互相不了解，因此他尽量收敛自己的锋芒"},{"k":"B","t":"小方只想在现在的岗位上工作，没有长远规划，常常以不会为理由推脱各项工作"},{"k":"C","t":"学校要求匿名对教师进行评价，小林虽然不喜欢张老师，但还是给她的评价写了“优”"},{"k":"D","t":"小丁随便报了个旅行团到陌生城市旅行，在旅行中大胆尝试不同的穿衣风格，释放真实的自己"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“不记姓名或相互不了解的情况”、“个体独立性、自主性得到充分体现”。<br>第二步：逐一分析选项。<br>A项：小刘到了新成立的公司，符合“不记姓名或相互不了解的情况”，但小刘收敛自己的锋芒，没有真正地展现自己，不符合“个体独立性、自主性得到充分体现”，不符合定义，排除； <br>B项：小方在现在的岗位上工作，不清楚是否是“相互不了解的情况”，常常以不会为理由推脱各项工作，不清楚是否真的不会，不符合“个体独立性、自主性得到充分体现”，不符合定义，排除；<br>C项：小林不喜欢张老师，但还是评价了“优”，并没有展现自主性，不符合“个体独立性、自主性得到充分体现”，不符合定义，排除；<br>D项：小丁到陌生城市旅行，符合“不记姓名或相互不了解的情况”，在旅行中释放真实的自己，符合“个体独立性、自主性得到充分体现”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":53,"pid":"pc62258248f"},{"qid":"13504340","no":19,"type":"定义判断","module":"判断推理","stem":"<p>非组织公众就是在公共关系对象中，处于无组织状态的个体的总和，非组织公众一般包括流散型公众、聚散型公众、周期型公众和固定型公众。①流散型公众：极为分散的最不稳定的公众；②聚散型公众：因某一临时事件、活动或某一共同问题临时聚集在一起的公众；③周期型公众：按一定的规律聚集在一起的公众；④固定型公众：由于兴趣、爱好、习惯的影响，比较集中地与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系的公众。<br>根据上述定义，下列对应正确的是：</p>","options":[{"k":"A","t":"乘坐北京开往上海高铁的旅客——④"},{"k":"B","t":"定期来某学校上课的函授班学员——③"},{"k":"C","t":"经常来社区棋牌室打牌的退休人员——②"},{"k":"D","t":"奥运会期间来田径体育场观看比赛的观众——①"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>①流散型公众：“极为分散”、“不稳定”；<br>②聚散型公众：“因某一临时事件、活动或某一共同问题”、“临时聚集”；<br>③周期型公众：“按一定的规律聚集在一起”；<br>④固定型公众：“由于兴趣、爱好、习惯的影响”、“与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系”。<br>第二步：逐一分析选项。<br>A项：乘坐北京开往上海高铁的旅客，“乘坐高铁”不符合“由于兴趣、爱好、习惯的影响”、“与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系”，不符合“固定型公众”定义，对应错误，排除；<br>B项：定期来某学校上课的函授班学员，“定期”符合“按一定的规律聚集在一起”，符合“周期型公众”定义，对应正确，当选；<br>C项：经常来社区棋牌室打牌的退休人员，“打牌”符合“由于兴趣、爱好、习惯的影响”，“经常来社区棋牌室”符合“与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系”，符合“固定型公众”定义，不符合“聚散型公众”定义，对应错误，排除；<br>D项：奥运会期间来田径体育场观看比赛的观众，“奥运会期间”“看比赛”符合“因某一临时事件、活动或某一共同问题”、“临时聚集”，符合“聚散型公众”定义，不符合“流散型公众”定义，对应错误，排除。<br>故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":54,"pid":"pc62258248f"},{"qid":"13504349","no":20,"type":"定义判断","module":"判断推理","stem":"<p>组合是指把多项看似不相关的事物通过想象加以联接，从而使之变成新的整体。按照组合方式不同，组合可分为三种：同类组合是指若干相同事物的组合；异类组合是指两种或两种以上不同事物的组合；重组组合是指分解事物的原来组合，再按照新的目标重新组合。<br>根据上述定义，下列属于重组组合的是：</p>","options":[{"k":"A","t":"在手机壳背后安一个钢圈，制成带支架的手机壳"},{"k":"B","t":"用100根雪糕棍制作成房子、坦克等手工艺制品"},{"k":"C","t":"在台灯底座安装紫外线灭蚊装置，设计出灭蚊灯"},{"k":"D","t":"将原来拼装成大风车的积木拆开，再拼装成飞机"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>组合：“把多项看似不相关的事物”、“通过想象加以联接”；<br>同类组合：“若干相同事物的组合”；<br>异类组合：“两种或两种以上不同事物的组合”；<br>重组组合：“分解事物的原来组合，再按照新的目标重新组合”。<br>第二步：逐一分析选项。<br>A项：在手机壳背后安装一个钢圈，是在原有的基础上加上一个东西，并未分解事物的原来组合，不符合“分解事物的原来组合，再按照新的目标重新组合”，不符合“重组组合”定义，排除；<br>B项：用100根雪糕棍制作成房子等手工艺制品，是同一种事物的组合，符合“若干相同事物的组合”，符合“同类组合”定义，不符合“重组组合”定义，排除；<br>C项：在台灯底座安装紫外线灭蚊装置，是在台灯底座原有的基础上安装，并未分解事物的原来组合，不符合“分解事物的原来组合，再按照新的目标重新组合”，不符合“重组组合”定义，排除；<br>D项：将原来拼装成大风车的积木拆开，符合“分解事物的原来组合”，再拼装成飞机，符合“再按照新的目标重新组合”，符合“重组组合”定义，当选。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":55,"pid":"pc62258248f"},{"qid":"13504269","no":21,"type":"类比推理","module":"判断推理","stem":"<p>欲穷千里目：更上一层楼</p>","options":[{"k":"A","t":"为唤春来争艳朵：甘将香化育花泥"},{"k":"B","t":"不经一番寒彻骨：怎得梅花扑鼻香"},{"k":"C","t":"欲上高楼去避愁：愁还随我上高楼"},{"k":"D","t":"抛开俗事陪山坐：才得闲心听水歌"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“欲穷千里目，更上一层楼”的意思是想要看到千里之外的风光，那就要再登上更高的一层城楼，其中“欲穷千里目”是目的，“更上一层楼”是方式，二者为方式目的的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“为唤春来争艳朵，甘将香化育花泥”的意思是为了春天的花朵绽放，甘愿化作花泥，其中“为唤春来争艳朵”是目的，“甘将香化育花泥”是方式，二者为方式目的的对应关系，与题干逻辑关系一致，当选；<br>B项：“不经一番寒彻骨，怎得梅花扑鼻香”的意思是只有经历艰苦（寒彻骨），才能获得美好的结果（梅花香），二者不是方式目的的对应关系，与题干逻辑关系不一致，排除；<br>C项：“欲上高楼去避愁，愁还随我上高楼”的意思是心想到高楼上观看美景躲避忧愁，忧愁还是跟着我上了高楼，二者不是方式目的的对应关系，与题干逻辑关系不一致，排除；<br>D项：“抛开俗事陪山坐，才得闲心听水歌”的意思是放下世俗的琐事、烦恼和欲望，与山为伴，亲近自然，才能获得内心的闲适与安宁，聆听流水的声音，感受自然的美好，二者为条件结果的对应关系，不是方式目的的对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":56,"pid":"pc62258248f"},{"qid":"13504387","no":22,"type":"类比推理","module":"判断推理","stem":"<p>覆：盖：覆盖</p>","options":[{"k":"A","t":"寒：酸：寒酸"},{"k":"B","t":"厚：重：厚重"},{"k":"C","t":"喉：舌：喉舌"},{"k":"D","t":"抚：摸：抚摸"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“覆”、“盖”、“覆盖”均指遮盖，三者是近义关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“寒”指冷、穷困，“酸”指像醋的气味或味道，二者不是近义关系，与题干逻辑关系不一致，排除；<br>B项：“厚”指扁平物体上下两个面的距离大，“重”指分量较大、程度深，二者不是近义关系，与题干逻辑关系不一致，排除；<br>C项：“喉”指介于咽和气管之间的部分，“舌”指舌头，二者不是近义关系，与题干逻辑关系不一致，排除；<br>D项：“抚”、“摸”、“抚摸”均指用手指轻轻触摸，三者是近义关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":57,"pid":"pc62258248f"},{"qid":"13504285","no":23,"type":"类比推理","module":"判断推理","stem":"<p>发炎：发烧</p>","options":[{"k":"A","t":"饥饿：烧烤"},{"k":"B","t":"学习：考试"},{"k":"C","t":"祭祀：缅怀"},{"k":"D","t":"缺铁：贫血"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>发炎表现为红、肿、热、痛和功能障碍，所以发炎可以导致发烧，二者为因果对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：饥饿会导致胃肠疾病或者低血糖等，不会导致烧烤，二者不是因果对应关系，与题干逻辑关系不一致，排除；<br>B项：学习是为了准备考试，二者为方式目的的对应关系，与题干逻辑关系不一致，排除；<br>C项：祭祀是一种缅怀的方式，二者为方式目的的对应关系，与题干逻辑关系不一致，排除；<br>D项：缺铁可以导致贫血，二者为因果对应关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":58,"pid":"pc62258248f"},{"qid":"13504319","no":24,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 斜拉桥 相当于 燃油车 对于（    ）</p>","options":[{"k":"A","t":"拱式桥；摩托车"},{"k":"B","t":"钢架桥；人力车"},{"k":"C","t":"人行桥；网约车"},{"k":"D","t":"独木桥；违章车"}],"answer":"C","multi":false,"explanation":"<p>逐一代入选项。<br>A项：拱式桥和斜拉桥是两种不同结构类型的桥，二者是并列关系；有的摩托车是燃油车，有的燃油车是摩托车，有的摩托车不是燃油车，有的燃油车不是摩托车，二者是交叉关系，前后逻辑关系不一致，排除；<br>B项：有的钢架桥是斜拉桥，有的斜拉桥是钢架桥，有的钢架桥不是斜拉桥，有的斜拉桥不是钢架桥，二者是交叉关系；燃油车和人力车是两种不同动力来源的车，二者是并列关系，前后逻辑关系不一致，排除；<br>C项：有的人行桥是斜拉桥，有的斜拉桥是人行桥，有的人行桥不是斜拉桥，有的斜拉桥不是人行桥，二者是交叉关系；有的网约车是燃油车，有的燃油车是网约车，有的网约车不是燃油车，有的燃油车不是网约车，二者是交叉关系，前后逻辑关系一致，当选；<br>D项：独木桥和斜拉桥是两种不同结构类型的桥，二者是并列关系；有的违章车是燃油车，有的燃油车是违章车，有的违章车不是燃油车，有的燃油车不是违章车，二者是交叉关系，前后逻辑关系不一致，排除。<br>故正确答案为C。<br>注：有同学可能会认为B项的钢架桥和斜拉桥是按照结构划分的两种不同的桥梁，但是按照结构划分的应为“刚”架桥，选项中的“钢”架桥为按照材料划分的，二者并不相同。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":59,"pid":"pc62258248f"},{"qid":"12882038","no":25,"type":"类比推理","module":"判断推理","stem":"<p>讲解：精讲</p>","options":[{"k":"A","t":"山村：荒村"},{"k":"B","t":"火器：武器"},{"k":"C","t":"语词：热词"},{"k":"D","t":"乐事：趣事"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“精讲”一般指对某一知识点或某一内容进行深入、细致、有条理、全面的讲解，“精讲”是一种“讲解”，二者为种属关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“山村”指山区的村庄，“荒村”指荒僻的村落，有的山村是荒村，有的山村不是荒村，有的荒村是山村，有的荒村不是山村，二者为交叉关系，与题干逻辑关系不一致，排除；<br>B项：“火器”指的是利用炸药等的爆炸或燃烧性能起杀伤破坏作用的武器，“火器”是一种“武器”，二者为种属关系，但词语顺序与题干相反，与题干逻辑关系不一致，排除；<br>C项：“语词”指词、词组，“热词”指一个时期内使用频率极高的词语，“热词”是一种“语词”，二者为种属关系，与题干逻辑关系一致，当选；<br>D项：“乐事”指令人高兴的事，“趣事”指有趣的事，有的乐事是趣事，有的乐事不是趣事，有的趣事是乐事，有的趣事不是乐事，二者为交叉关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":60,"pid":"pc62258248f"},{"qid":"13504373","no":26,"type":"逻辑判断","module":"判断推理","stem":"<p>汉朝建立后，在秦咸阳故都的基础上建立了长安城。经过西汉末年、东汉末年和魏晋南北朝期间的长期战乱，长安城日益凋敝。城门、宫殿、武库及城南的礼制建筑等都在战火中被毁，唐朝建立后，虽然汉都长安已破败不堪，但是唐长安城仍与其关联密切。有学者认为，汉长安城实际上成为了唐长安城的一部分。<br>以下哪项如果为真，最能支持上述学者的观点？</p>","options":[{"k":"A","t":"汉长安城的渭南内城被划入了唐长安城西北角的禁苑，成为专供皇室游猎的场所"},{"k":"B","t":"唐朝政府设有专门的机构管理汉长安城的主要遗迹，还曾对汉未央宫进行过修葺扩建"},{"k":"C","t":"至唐朝时，汉长安城的城墙城门、部分宫殿、武库、官署和角楼等建筑及道路都还保留完好"},{"k":"D","t":"隋朝建立都城时，曾从汉长安城的宫室建筑拆取了一些大型建材，这些都为后世的唐朝所继承"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：汉长安城实际上成为了唐长安城的一部分。<br>论据：无。<br>本题只有论点，没有论据，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：汉长安城的渭南内城被划入了唐长安城西北角的禁苑，说明汉长安城确实成为了唐长安城的一部分，补充论据，可以加强，当选；<br>B项：唐朝政府会管理汉长安城的主要遗迹并修葺扩建过汉未央宫，但汉长安城的主要遗迹和汉未央宫是否被纳入了唐长安城并不清楚，为不明确项，无法加强，排除；<br>C项：汉长安城的部分建筑及道路至唐朝时仍保留完好，但其是否被纳入了唐长安城并不清楚，为不明确项，无法加强，排除；<br>D项：唐朝部分建筑的“建材”来自汉长安城的宫室建筑，而论点讨论的是汉长安“城”实际上成为了唐长安城的一部分，建材无法代表城池，话题不一致，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":61,"pid":"pc62258248f"},{"qid":"13504379","no":27,"type":"逻辑判断","module":"判断推理","stem":"<p>自己烧水喝与直接喝包装水，哪一种更健康？一种观点认为，包装水中含有大量的微塑料，直接喝包装水会使微塑料进入体内，危害健康，因此自己烧水喝比直接喝包装水健康，另一种观点则认为，当前微塑料污染无处不在，海洋、污水、淡水、饮用水中均含有微塑料，因此自己烧水喝与直接喝包装水对健康的影响是一样的。<br>以下哪项如果为真，最能削弱第二种观点？</p>","options":[{"k":"A","t":"在日常饮食中应尽量减少微塑料进入体内"},{"k":"B","t":"把水烧开后，可以除去高达84%的微塑料"},{"k":"C","t":"自然水域中的微塑料已危害到野生动物健康"},{"k":"D","t":"微塑料可以进入血液，甚至抵达心脏和大脑"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：自己烧水喝与直接喝包装水对健康的影响是一样的。<br>论据：当前微塑料污染无处不在，海洋、污水、淡水、饮用水中均含有微塑料。<br>本题论点讨论是自己烧水喝与直接喝包装水对健康的影响相同，论据讨论的是所有水中都含有微塑料，二者话题一致，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：指出日常饮食中应该减少微塑料的摄入，与论点讨论的自己烧水喝与直接喝包装水对健康的影响相同无关，话题不一致，无法削弱，排除；<br>B项：指出水烧开后可以除去84%的微塑料，说明自己烧水喝比直接喝包装水摄入的微塑料少，因此自己烧水喝与直接喝包装水对健康的影响不一样，削弱论点，可以削弱，当选；<br>C项：指出自然水域中的微塑料危害到“野生动物”的健康，与论点讨论的“人体健康”无关，话题不一致，无法削弱，排除；<br>D项：指出微塑料的危害，但不清楚自己烧的水与直接饮用包装水中的微塑料含量是否相同，为不明确项，无法削弱，排除。<br>故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":62,"pid":"pc62258248f"},{"qid":"13504369","no":28,"type":"逻辑判断","module":"判断推理","stem":"<p>研究人员比较了过去几年自动驾驶车辆和人类驾驶车辆的相关数据发现，一般情况下，与人类驾驶相比，自动驾驶车辆在执行常规驾驶任务，如保持车道位置和根据车流调整位置时更安全，研究人员认为，以自动驾驶车辆代替人类驾驶车辆上路可以大大减少交通事故。<br>上述结论需要补充以下哪项作为前提？</p>","options":[{"k":"A","t":"当前交通事故主要发生在常规驾驶任务中"},{"k":"B","t":"过去几年自动驾驶车辆技术水平发展迅速"},{"k":"C","t":"自动驾驶车辆可以为道路交通提供精准导航"},{"k":"D","t":"自动驾驶车辆和人类驾驶车辆存在风险差异"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：以自动驾驶车辆代替人类驾驶车辆上路可以大大减少交通事故。<br>论据：一般情况下，与人类驾驶相比，自动驾驶车辆在执行常规驾驶任务，如保持车道位置和根据车流调整位置时更安全。<br>论据和论点都在说自动驾驶车辆比人类驾驶更安全，二者话题一致，且提问方式为“前提”，加强优先考虑补充必要条件。<br>第二步：逐一分析选项。<br>A项：选项表明当前交通事故主要发生在常规驾驶任务中，如果该项不成立，即交通事故大多都不是发生在常规驾驶任务中，那么就无法根据论据“在执行常规驾驶任务时，自动驾驶车辆比人类驾驶更安全”得出论点，因此该项是论点成立的必要条件，可以加强，当选；<br>B项：选项表明过去几年自动驾驶车辆技术水平发展迅速，但不明确以自动驾驶车辆代替人类驾驶车辆上路是否可以减少交通事故，无法加强，排除；<br>C项：选项表明自动驾驶车辆可以为道路交通提供精准导航，说的是自动驾驶车辆的导航能力，而论点说的是自动驾驶车辆的安全性，话题不一致，无法加强，排除；<br>D项：选项表明自动驾驶车辆和人类驾驶车辆存在风险差异，但不明确以自动驾驶车辆代替人类驾驶车辆上路是否可以减少交通事故，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":63,"pid":"pc62258248f"},{"qid":"13504367","no":29,"type":"逻辑判断","module":"判断推理","stem":"<p>某商场发生了一起电梯坠落事故，对于事故发生的原因，甲、乙二人展开了讨论。甲说：此次电梯坠落事故的责任在于电梯维保单位，事故电梯维保单位没有严格按照安全技术规范要求对电梯进行实质性维保。乙说：此次电梯坠落事故的发生与事故电梯维保单位没有关系，事故电梯向下运行过程中，对重反绳轮滚动轴承因疲劳剥落失效，出现了卡死现象，这才是导致事故发生的原因。<br>以下哪项如果为真，最能削弱乙的意见？</p>","options":[{"k":"A","t":"事故电梯维保单位负责保养的其他电梯并没有出现类似事故，目前都在正常运行"},{"k":"B","t":"由于安全监管等相关部门的重视，对所有电梯元件的生产、安装、维保都有严格的规定，由此导致的事故数量呈现逐年下降趋势"},{"k":"C","t":"当前出现的电梯事故的主要原因是人的不安全行为，如超载、反复开关梯门、在电梯运行过程中蹦跳等，而非电梯本身的不安全状态"},{"k":"D","t":"事故电梯维保单位没有严格按照安全技术规范要求对电梯进行实质性维保，导致对重反绳轮滚动轴承老化，出现卡死现象"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：此次电梯坠落事故的发生与事故电梯维保单位没有关系，事故电梯向下运行过程中，对重反绳轮滚动轴承因疲劳剥落失效，出现了卡死现象，这才是导致事故发生的原因。<br>论据：无。<br>本题只有论点没有论据，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项说的是事故电梯维保单位负责保养的“其他电梯”正常运行，但不能说明题干商场发生事故的电梯问题与维保单位无关，无法削弱，排除；<br>B项：该项说的是安全监管等相关部门对电梯元件的规定及事故数量下降趋势，与论点讨论的此次电梯坠落事故发生的原因无关，为无关项，无法削弱，排除；<br>C项：该项说的是电梯事故的主要原因是人的不安全行为，而非电梯本身的不安全状态，但不明确人的不安全行为与论点讨论的原因之间的关系，为不明确项，无法削弱，排除；<br>D项：该项说的是事故电梯维保单位没有严格按照要求对电梯进行实质性维保，导致对重反绳轮滚动轴承老化，出现卡死现象，说明从根本上来说，是电梯维保单位没有严格按照要求对电梯进行实质性维保导致了事故的发生，直接削弱了乙的观点，可以削弱，当选。<br>故正确答案为D。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"pc62258248f"},{"qid":"13504393","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>一项有关办公模式的研究中，研究机构选择了全球最大在线旅行社之一的M公司员工进行了实验，该公司员工约有1600人，研究发现，与每天到办公室工作相比，每周居家办公两天的混合办公模式不仅没有影响员工的工作表现，还能有效降低人力成本。因此，研究机构认为：混合办公模式是公司运营的有效模式。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"M公司推行混合办公模式后，员工辞职率下降了33%"},{"k":"B","t":"M公司中，采用混合办公模式人员和非混合办公模式人员在晋升方面机会均等"},{"k":"C","t":"近几年来全球约1亿员工采用混合工作制，M公司所在国有很多企业都赞成该模式"},{"k":"D","t":"如果员工每周5天不在办公室工作，员工培训指导以及公司文化都会受到较大影响"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：混合办公模式是公司运营的有效模式。<br>论据：一项对M公司员工约1600人进行的实验发现，与每天到办公室工作相比，每周居家办公两天的混合办公模式不仅没有影响员工的工作表现，还能有效降低人力成本。<br>本题论据说的是混合办公模式的一些优势，论点说的是混合办公模式是公司运营的有效模式，二者话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项说的是混合办公模式降低了M公司的辞职率，提升了员工的稳定性，有利于公司运营，补充论据，可以加强，当选；<br>B项：该项说的是混合办公模式对“人员晋升”的影响，不涉及公司运营，话题不一致，无法加强，排除；<br>C项：该项说的是混合办公模式的使用情况和其他企业的态度，不涉及公司运营，话题不一致，无法加强，排除；<br>D项：该项说的是混合办公模式产生的负面影响，不利于公司运营，具有削弱作用，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":65,"pid":"pc62258248f"},{"qid":"13504368","no":31,"type":"逻辑判断","module":"判断推理","stem":"<p>研究人员调查了负面情绪（包括愤怒、焦虑和悲伤）是否会对人体产生不利影响。研究中，280名成年人被随机分配4项情绪任务之一，包括回忆让他们愤怒的个人经历；回忆令自己感到焦虑的事件；阅读一系列引发悲伤的令人沮丧的句子；或者反复从1数到100以诱发中性情绪状态。研究发现，从任务完成后的0分钟到40分钟，回忆愤怒经历会导致血管舒张能力受损。40分钟后，这种状况才消失，而相较于愤怒，焦虑和悲伤情绪并没有引发血管内壁功能的显著变化。研究人员据此认为，愤怒会增加患动脉粥样硬化的风险。<br>上述论证的成立需要补充以下哪项作为前提？</p>","options":[{"k":"A","t":"血管舒张能力受损引发血管内壁功能的显著变化"},{"k":"B","t":"回忆愤怒的经历与心血管疾病之间存在显著关联"},{"k":"C","t":"血管舒张能力受损会增加患动脉粥样硬化的风险"},{"k":"D","t":"研究开始前，受试者都未检出血管舒张能力受损"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：愤怒会增加患动脉粥样硬化的风险。<br>论据：回忆愤怒经历会导致血管舒张能力受损，而焦虑和悲伤情绪并没有引发血管内壁功能的显著变化。<br>本题论点说的是“愤怒”与“患动脉粥样硬化的风险”之间的关系，论据说的是“愤怒”与“血管舒张能力受损”之间的关系，二者话题不一致，且提问方式为“前提”，加强优先考虑搭桥，即在“血管舒张能力受损”与“患动脉粥样硬化的风险”之间建立联系。<br>第二步：逐一分析选项。<br>A项：指出血管舒张能力受损引发血管内壁功能的显著变化，但不明确是否会增加患动脉粥样硬化的风险，不明确选项，无法加强，排除；<br>B项：指出回忆愤怒经历与心血管疾病之间存在关联，但不明确是否会增加患动脉粥样硬化的风险，不明确选项，无法加强，排除；<br>C项：指出血管舒张能力受损会增加患动脉粥样硬化的风险，在“血管舒张能力受损”与“患动脉粥样硬化的风险”之间建立了联系，搭桥选项，是论证成立的前提，当选；<br>D项：指出实验前受试者都未检出血管舒张能力受损，说明实验具有科学性，但论点讨论的是患动脉粥样硬化的风险，所以不是论证成立的前提，排除。<br>故正确答案为C。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":66,"pid":"pc62258248f"},{"qid":"13504366","no":32,"type":"逻辑判断","module":"判断推理","stem":"<p>深度睡眠阶段，人体会从大脑中移除不想要的或可能有害的物质，包括阿尔茨海默病中聚集的主要蛋白质，如Tau蛋白。阿尔茨海默病患者的一种病理变化是脑内Tau蛋白过度磷酸化，在细胞内堆积形成神经原纤维缠结。因此有研究者认为，深度睡眠不足会增加罹患阿尔茨海默病的风险。<br>以下哪项如果为真，最能削弱上述结论?</p>","options":[{"k":"A","t":"神经原纤维缠结与神经细胞死亡和认知功能障碍密切相关"},{"k":"B","t":"携带阿尔茨海默病高风险基因的人更可能出现深度睡眠不足"},{"k":"C","t":"精神刺激、创伤、神经系统疾病等因素都可诱发阿尔茨海默病"},{"k":"D","t":"年轻人的深度睡眠占睡眠时间的20%~25%，老年人只占5%~7%"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：深度睡眠不足会增加罹患阿尔茨海默病的风险。<br>论据：深度睡眠阶段，人体会从大脑中移除不想要的或可能有害的物质，包括阿尔茨海默病中聚集的主要蛋白质，如Tau蛋白。阿尔茨海默病患者的一种病理变化是脑内Tau蛋白过度磷酸化，在细胞内堆积形成神经原纤维缠结。<br>本题论点和论据讨论的都是深度睡眠和患阿尔茨海默病的风险之间的关系，二者话题一致，优先考虑削弱论点，且论点包含因果关系，还可以考虑因果倒置或他因削弱。<br>第二步：逐一分析选项。<br>A项：该项指出神经原纤维缠结与神经细胞死亡和认知功能障碍密切相关，但是，由于认知功能障碍包含的疾病类型诸多，不一定只有阿尔茨海默病，因此选项不明确，无法削弱，排除；<br>B项：该项指出携带阿尔茨海默病高风险基因的人更可能出现深度睡眠不足，说明深度睡眠不足可能是由阿尔茨海默病的遗传风险（高风险基因）引起的，而不是深度睡眠不足导致了阿尔茨海默病，因此选项为因果倒置，可以削弱，当选；<br>C项：该项说明精神刺激、创伤、神经系统疾病等因素都可诱发阿尔茨海默病，提出了其他可能的阿尔茨海默病的风险因素，但并未说明这些因素与深度睡眠的关系，因此无法削弱深度睡眠不足和阿尔茨海默病之间的关系，话题不一致，无法削弱，排除；<br>D项：该项指出年轻人和老年人深度睡眠在睡眠时间中的占比，说明深度睡眠的比例随着年龄的增长而减少，但它并没有说明年轻人和老年人中患阿尔茨海默病的占比，因此无法直接削弱深度睡眠不足和阿尔茨海默病之间的关系，话题不一致，无法削弱，排除。<br>故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":67,"pid":"pc62258248f"},{"qid":"13504381","no":33,"type":"逻辑判断","module":"判断推理","stem":"<p>为研究雄性小鼠肠道微生物组对后代健康的影响，研究人员给雄性小鼠注射了6周抗生素，导致它们肠道微生物多样性和丰富度下降，结果发现这些小鼠的后代出生时体重较轻、生长严重受限以及过早死亡的概率更高，研究人员认为，这一效应与雄性生殖系统对微生物组失衡的反应有关，这种反应可能会增加胎盘功能不全的风险，因此，雄性小鼠肠道微生物组紊乱可能会影响后代健康。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"在雌性小鼠受孕前，若紊乱的雄性小鼠肠道微生物组得到恢复，则能降低后代不健康的风险"},{"k":"B","t":"研究中雄性小鼠生殖系统对微生物组失衡的反应包括激素信号受损和睾丸代谢物特征改变"},{"k":"C","t":"导致雄性小鼠肠道微生物组紊乱的环境因素会引发宿主的生理和疾病反应"},{"k":"D","t":"对哺乳动物而言，雄性的健康状况很有可能会遗传给后代"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：雄性小鼠肠道微生物组紊乱可能会影响后代健康。<br>论据：研究人员给雄性小鼠注射了6周抗生素，导致它们肠道微生物多样性和丰富度下降，结果发现这些小鼠的后代出生时体重较轻、生长严重受限以及过早死亡的概率更高，研究人员认为，这一效应与雄性生殖系统对微生物组失衡的反应有关，这种反应可能会增加胎盘功能不全的风险。<br>本题论点和论据均在讨论雄性小鼠肠道微生物对后代健康的影响，论点论据话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：选项说在雌性小鼠受孕前，紊乱的雄性小鼠肠道微生物组如果恢复，则能降低后代不健康的风险，补充反面论据说明雄性小鼠肠道微生物组紊乱确实会影响后代健康，补充论据，可以加强，当选；<br>B项：选项说研究中雄性小鼠生殖系统对微生物组失衡的反应包括哪些特征改变，但论点讨论的是雄性小鼠肠道微生物组紊乱是否会影响后代健康，话题不一致，无法加强，排除；<br>C项：选项说导致雄性小鼠肠道微生物组紊乱的环境因素会引发宿主的生理和疾病反应，但论点讨论的是雄性小鼠肠道微生物组紊乱是否会影响后代健康，话题不一致，无法加强，排除；<br>D项：选项说哺乳动物雄性的健康状况很有可能会遗传给后代，但是不确定雄性小鼠肠道微生物组紊乱是否会影响后代健康，为不明确选项，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":68,"pid":"pc62258248f"},{"qid":"13504491","no":34,"type":"逻辑判断","module":"判断推理","stem":"<p>某研究团队发布了一项关于睡眠习惯、时间与癌症风险的研究。研究分析了近1.5万人，发现睡眠时间短导致癌症风险升高，和睡眠时间为6-8小时的参与者相比，夜间睡眠时间少于6小时的人，患癌风险升高41%，和午睡时间多于60分钟的参与者相比，从不午睡的参与者患癌风险升高60%。<br>以下哪项如果为真，最能加强上述观点：</p>","options":[{"k":"A","t":"睡眠时间短会损害免疫功能、降低人体对肿瘤细胞的识别和消灭能力"},{"k":"B","t":"人类环境、卫生资源和睡眠习惯的变化，导致癌症发病原因发生了变化"},{"k":"C","t":"夜间睡眠时间短或不午睡的参与者，大多年龄较大且缺少锻炼，健康状况不佳"},{"k":"D","t":"和总睡眠时间为7-8小时的参与者相比，总睡眠时间少于7小时的男性，患癌风险升高69%"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：睡眠时间短导致癌症风险升高。<br>论据：和睡眠时间为6-8小时的参与者相比，夜间睡眠时间少于6小时的人，患癌风险升高41%，和午睡时间多于60分钟的参与者相比，从不午睡的参与者患癌风险升高60%。<br>论据在说夜间睡眠时间短和从不午睡的参与者患癌风险高，论点在说睡眠时间短导致癌症风险升高，二者话题一致，加强考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项指出“睡眠时间短会损害免疫功能、降低人体对肿瘤细胞的识别和消灭能力”，解释了睡眠时间短与患癌风险高之间的关系，补充论据，可以加强，保留；<br>B项：该项指出人类环境、卫生资源和睡眠习惯的变化使得癌症发病原因发生了变化，并未说明睡眠时间短和癌症风险高有关系，无法加强，排除；<br>C项：该项指出夜间睡眠时间短或不午睡的参与者，年龄较大且缺少锻炼，但并未说明年龄较大、缺少锻炼是否癌症风险就会高，为不明确项，无法加强，排除；<br>D项：该项指出睡眠时间短于7小时的男性患癌风险升高了69%，举例说明睡眠时间短与患癌风险高之间存在关系，补充论据，可以加强，保留。<br>比较A、D两项，A项是解释原因，D项举例，解释原因的加强力度大于举例，A项的加强力度更强。<br>故正确答案为A。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":69,"pid":"pc62258248f"},{"qid":"13504380","no":35,"type":"逻辑判断","module":"判断推理","stem":"<p>某公司举办年会，所有表演街舞的员工都表演了民族舞，所有表演民族舞的员工都表演了唱歌，有些表演吉他演奏的员工表演了诗朗诵，所有表演吉他演奏的员工都没有表演唱歌。<br>根据上述陈述，不能推出以下哪项？</p>","options":[{"k":"A","t":"所有表演街舞的员工都表演了唱歌"},{"k":"B","t":"有些表演街舞的员工表演了吉他演奏"},{"k":"C","t":"有的表演诗朗诵的员工没有表演唱歌"},{"k":"D","t":"所有表演吉他演奏的员工都没有表演民族舞"}],"answer":"B","multi":false,"explanation":"<p>第一步：翻译题干。</p><p>①表演街舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演民族舞；</p><p>②表演民族舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演唱歌；</p><p>③有的表演吉他演奏<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演诗朗诵；</p><p>④表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演唱歌；</p><p>条件③可换位为：⑤有的表演诗朗诵<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演吉他演奏；</p><p>可将条件①②逆否后和条件④⑤串联推出：⑥有的表演诗朗诵<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演唱歌<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演民族舞<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演街舞。</p><p>第二步：逐一分析选项。</p><p>A项：翻译为表演街舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演唱歌，“表演街舞”是对条件⑥的否后，否后必否前，可以推出，排除；</p><p>B项：翻译为有的表演街舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演吉他演奏，根据条件⑥可知，表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演街舞，将其逆否后为，表演街舞<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演吉他演奏，“所有A不是B”与“有的A是B”互为矛盾关系，无法推出，当选；</p><p>C项：翻译为有的表演诗朗诵<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演唱歌，根据条件⑥可以推出，排除；</p><p>D项：翻译为表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演民族舞，“表演吉他演奏”是对条件⑥的肯前，肯前必肯后，可以推出，排除。</p><p>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年广西区考公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":70,"pid":"pc62258248f"}]};
